// AiXenix Cosmos Lab: the galaxy-scale travel model, types. Pure data, no DOM, no engine.
//
// Scale hierarchy: universe (galaxies) -> galaxy (components, octree cells) -> stars -> local system (a CosmicCore scene).
// Units: parsecs (pc), float64, for every universe/galaxy position; solar units for stars; SI inside local scenes.
// Universe frame: Galactocentric Cartesian, astropy convention: origin at the Galactic Centre (Sgr A*), +x from the Sun's
// projection towards the centre (the Sun is at x ≈ −8.12 kpc), +y towards Galactic longitude 90° (the Galactic rotation
// at the Sun), +z towards the North Galactic Pole. Galaxies are a static snapshot: no galaxy rotation, orbit, collision
// or galaxy-wide N-body is computed. A local system's physics is CosmicCore (WASM), nothing else.
//
// Procedural model: each galaxy has a declared, finite procedural capacity (`starCount`, an exact integer < 2^53). Its
// stars are numbered 0..starCount-1 (the star id); every id resolves in O(tree depth) to one exact star (component,
// octree leaf cell, index, position, properties) without storing any star. This is model address capacity, never a
// catalogue size and never a discovery: observed catalogue stars are a separate sparse overlay.

import type { LocalizedText } from '../content/catalog';
import type { SceneFile } from '../content/catalog';

export type { LocalizedText };
export type Vec3 = [number, number, number];

/** Model/address version: addresses and generated systems carry it; any change that alters a star or system bumps it. */
export const COSMOS_MODEL_VERSION = 'c1';

/** observed: catalogue measurement; reconstructed: derived from observations by stated assumptions; procedural: generated. */
export type Provenance = 'observed' | 'reconstructed' | 'procedural';

// ---- inputs (content-owned observed data; structural, so content's GalaxyInfo / KnownStar satisfy them) ---------------

export type GalaxyKind = 'spiral' | 'barred_spiral' | 'lenticular' | 'elliptical' | 'dwarf_elliptical' | 'irregular' | 'dwarf_spheroidal';

/** Observed galaxy metadata the model reads (content's GalaxyInfo is a superset). */
export interface GalaxyInput {
  id: string; // [a-z0-9_]+
  name: LocalizedText;
  kind: GalaxyKind;
  raDeg: number;
  decDeg: number;
  distanceKpc: { value: number };
  /** Galactocentric position (pc). Absent: computed from ra/dec/distance with this module's frame. The Milky Way: [0,0,0]. */
  galactocentricPc?: Vec3;
  diameterKpc?: number;
  axisRatio?: number;
  inclinationDeg?: number;
  positionAngleDeg?: number;
  stellarMassMsun?: number;
}

/** Observed star metadata the model reads (content's KnownStar is a superset). */
export interface KnownStarInput {
  id: string;
  name: LocalizedText;
  raDeg?: number;
  decDeg?: number;
  /** Heliocentric distance (pc). Absent/null only for the Sun (the frame anchor). */
  distancePc?: { value: number } | null;
  galactocentricPc?: Vec3;
  spectralType?: string;
  teffK?: number;
  massSun?: number;
  radiusSun?: number;
  luminositySun?: number;
  sceneId?: string;
  /** Object kind; absent: inferred from spectralType / names ('black hole', 'PSR', 'D…'). */
  objectKind?: 'star' | 'white_dwarf' | 'neutron_star' | 'pulsar' | 'black_hole';
  aliases?: string[];
}

/**
 * Model choices for one galaxy (core-owned, src/cosmos/params.ts): shapes and the declared capacity. Each value is
 * either cited (source id) or an explicit assumption; `listGalaxies` reports which.
 */
export interface GalaxyModelParams {
  capacity: number; // declared procedural star count (integer, <= 2e12)
  radiusPc: number; // truncation radius
  components: ComponentParams[];
  sources: string[];
  assumptions: string[];
}

export type ComponentKind = 'thin_disk' | 'thick_disk' | 'bulge' | 'bar' | 'halo' | 'spheroid' | 'clump';

export interface ComponentParams {
  id: string; // [a-z0-9]+, unique in the galaxy
  kind: ComponentKind;
  /** Share of the capacity (shares are normalised; counts are split exactly). */
  share: number;
  ageGyr: [number, number];
  feH: number;
  geometry: DiskGeometry | SpheroidGeometry;
}

export interface DiskGeometry {
  type: 'disk';
  scaleLengthPc: number;
  scaleHeightPc: number; // sech² scale height z0
  rMaxPc: number;
  zMaxPc: number;
  /** Spiral modulation: arms = 0 for none; contrast in [0, 0.9); logarithmic pitch; arm phase at rRefPc. */
  arms: number;
  armContrast: number;
  pitchDeg: number;
  armPhaseDeg: number;
  rRefPc: number;
}

export interface SpheroidGeometry {
  type: 'spheroid';
  profile: 'hernquist' | 'plummer';
  scalePc: number;
  rMaxPc: number;
  /** Axis ratios y/x and z/x (<= 1), rotation about the galaxy z axis (deg), centre offset (pc, galaxy frame). */
  qy: number;
  qz: number;
  angleDeg: number;
  offsetPc: Vec3;
}

// ---- the model -------------------------------------------------------------------------------------------------------

export interface GalaxySummary {
  id: string;
  name: LocalizedText;
  kind: GalaxyKind;
  centrePc: Vec3; // universe frame
  /** Galaxy frame axes in the universe frame: normal = galaxy +z, majorAxis = galaxy +x. */
  normal: Vec3;
  majorAxis: Vec3;
  radiusPc: number;
  thicknessPc: number;
  /** Declared procedural capacity: star ids are 0..modelStarCount-1 (exact integer < 2^53). */
  modelStarCount: number;
  components: { id: string; kind: ComponentKind; starCount: number; firstId: number }[];
  /** Field -> provenance of the numbers above: position/distance/orientation observed or reconstructed, shapes and capacity model choices. */
  provenance: Record<string, Provenance>;
  sources: string[];
  assumptions: string[];
}

/** Opaque universe handle built once from content's catalogue (buildUniverse). */
export interface Universe {
  version: string;
  galaxies: GalaxySummary[];
  /** Internal per-galaxy state (caches); do not inspect. */
  readonly internal: unknown;
}

// ---- stars -----------------------------------------------------------------------------------------------------------

/**
 * Procedural star address. String form (URL-safe, stable per model version): `c1.<galaxyId>.<id base36>`,
 * e.g. `c1.milky_way.1x2f9kq`. `id` is an exact integer in [0, modelStarCount).
 */
export interface StarAddress {
  version: string;
  galaxyId: string;
  id: number;
}

export type StellarStage = 'main_sequence' | 'giant' | 'white_dwarf' | 'neutron_star' | 'black_hole' | 'brown_dwarf';

interface StarBase {
  /** 'c1.<galaxy>.<id36>' for procedural stars, 'obs.<record id>' for observed ones. Stable; use as key and in URLs. */
  key: string;
  name: LocalizedText;
  galaxyId: string;
  positionPc: Vec3; // universe frame, float64
  massSun: number;
  radiusSun: number;
  teffK: number;
  luminositySun: number;
  spectralType: string; // 'G2V', 'M4V', 'K1III', 'DA', 'NS', 'BH', 'L5' ...
  stage: StellarStage;
}

export interface ModelStar extends StarBase {
  provenance: 'procedural';
  address: StarAddress;
  component: { id: string; kind: ComponentKind };
  /** Leaf cell of the octree (debug/sector info): depth and integer cell coordinates in the component's unit cube. */
  cell: { depth: number; xyz: Vec3; index: number };
  ageGyr: number;
  feH: number;
  /** Number of planets generateSystem will create (cheap, same draw). */
  planetCountHint: number;
}

export interface ObservedStar extends StarBase {
  provenance: 'observed';
  record: KnownStarInput;
  /** Fields not in the record, filled from spectral-type relations (listed; provenance 'reconstructed'). */
  reconstructed: string[];
}

export type CosmosStar = ModelStar | ObservedStar;

export type ResolveError = 'syntax' | 'version' | 'unknown_galaxy' | 'out_of_range';
export type ResolveResult = { ok: true; star: ModelStar } | { ok: false; error: ResolveError; message: string };

// ---- queries and rendering samples -----------------------------------------------------------------------------------

export interface StarsNearResult {
  stars: ModelStar[]; // sorted by distance from the centre
  /** Exact number of model stars inside the sphere when `truncated` is false; a lower bound otherwise. */
  modelCountInRadius: number;
  /** True when the star limit or the cell budget cut the search (then `stars` is a subset). */
  truncated: boolean;
  visitedCells: number;
}

/**
 * A rendering sample: `count` REAL model stars (ids[i] resolves to exactly positions[i]), drawn uniformly at random
 * over the model (or over a region), so each stands statistically for representedStars / count stars.
 * positions: pc relative to the galaxy centre in the galaxy frame (x = majorAxis, z = normal); float32 for the GPU.
 */
export interface GalaxySample {
  galaxyId: string;
  /** Positions are galaxy-local (x = majorAxis, y = normal × majorAxis, z = normal), relative to centrePc. */
  frame: 'galaxy';
  count: number;
  ids: Float64Array; // exact star ids (integers < 2^53)
  positions: Float32Array; // xyz * count
  colors: Float32Array; // linear rgb 0..1 * count
  brightness: Float32Array; // relative visual brightness (log-compressed luminosity) 0..1
  /**
   * Model stars the sample stands for: the whole capacity (exact) without a region; with a region, the estimate
   * (cell total × kept fraction) of the model stars inside the sphere (representedExact false).
   */
  representedStars: number;
  representedExact: boolean;
}

export interface SampleOptions {
  /** Default 0. Different seeds give different (equally valid) subsets. */
  seed?: number;
  /** Restrict to stars inside this sphere (universe frame pc). */
  region?: { centrePc: Vec3; radiusPc: number };
}

export interface SectorInfo {
  /** Octree cell containing the point at the chosen depth, per component: key 'comp/depth/x.y.z'. */
  key: string;
  depth: number;
  /** Exact model star count of that cell (cells are in model space; their physical size varies). */
  modelStarCount: number;
  /** Physical size of the cell around the point (pc, approximate bounding size). */
  sizePc: number;
  /** Expected stellar number density at the point (stars per pc³, from the model's analytic density). */
  densityPerPc3: number;
}

// ---- local systems ---------------------------------------------------------------------------------------------------

export interface SystemOptions {
  /** Upper bound on bodies (star + companion + planets + moons); default 12, range 1..32. */
  maxBodies?: number;
  /** Observed stars only: add procedural (hypothetical) planets. Default false: the observed star alone. */
  hypotheticalPlanets?: boolean;
}

/** A generated local system: a scene document in the data/Scenes schema, loadable by the engine's own parser. */
export type CosmosScene = SceneFile & {
  generator: {
    version: string; // 'aixenix.cosmos.system/c1'
    address: string; // star key
    galaxyId: string;
    seed: number;
    provenance: Provenance; // of the star
  };
};

// ---- flight ----------------------------------------------------------------------------------------------------------

export interface FlightOptions {
  /** Animation length bounds (s). Default 2..14 s, growing with log distance. */
  minSeconds?: number;
  maxSeconds?: number;
}

export interface FlightPlan {
  from: Vec3;
  to: Vec3;
  distancePc: number;
  durationS: number;
  /** Position (pc, universe frame) at animation time t in [0, durationS]; eased start/stop, logarithmic cruise. */
  positionAt(t: number): Vec3;
  /** Apparent speed at t: pc per animation second and as a multiple of c (a HUD figure, not a physical ship). */
  speedAt(t: number): { pcPerS: number; c: number };
}
