// AiXenix Cosmos Lab: deterministic hashing for the procedural model. Everything that decides star COUNTS (and so which
// address is which star) uses only 32-bit integer operations, IEEE-exact arithmetic and Math.sqrt (correctly rounded by
// the standard), so the octree and every id are identical in every JavaScript engine. Star properties derived later may
// use Math.exp/log/pow (engine libm); generated scenes quantise those values (see quantise) before use.

/** A 32-bit finaliser (lowbias32 by C. Wellons). */
export function mix32(h: number): number {
  h ^= h >>> 16;
  h = Math.imul(h, 0x7feb352d);
  h ^= h >>> 15;
  h = Math.imul(h, 0x846ca68b);
  h ^= h >>> 16;
  return h >>> 0;
}

/** Hash of a seed and one uint32 word. */
export function h2(seed: number, a: number): number {
  return mix32((seed ^ mix32(a + 0x9e3779b9)) >>> 0);
}

/** Hash chain over several uint32 words. */
export function hn(seed: number, a: number, b: number, c = 0, d = 0): number {
  let h = h2(seed, a);
  h = h2(h, b);
  h = h2(h, c);
  return h2(h, d);
}

const TWO32 = 4294967296;

/** The high and low 32-bit words of a non-negative safe integer (all 53 bits are used: no aliasing above 2^32). */
export function hi32(n: number): number {
  return Math.floor(n / TWO32) >>> 0;
}
export function lo32(n: number): number {
  return n % TWO32 >>> 0;
}

/** Hash of a seed and a 53-bit integer. */
export function hBig(seed: number, n: number): number {
  return h2(h2(seed, lo32(n)), hi32(n) ^ 0x51ed27);
}

/** FNV-1a over a string's UTF-16 code units, mixed. */
export function hashString(s: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return mix32(h >>> 0);
}

/** Uniform in [0, 1) from a hash (32 bits). */
export function u01(h: number): number {
  return h / TWO32;
}

/**
 * Uniform in the open interval (0, 1) from two hashes: (n + 0.5) / 2^52 with a 52-bit n. Both extremes are exactly
 * representable: 2^-53 for n = 0 and 1 - 2^-53 for n = 2^52 - 1 (a 53-bit numerator would round its top value to 1).
 */
export function u53(a: number, b: number): number {
  return ((a >>> 12) * TWO32 + (b >>> 0) + 0.5) / 4503599627370496;
}

function popcount(x: number): number {
  x = x - ((x >>> 1) & 0x55555555);
  x = (x & 0x33333333) + ((x >>> 2) & 0x33333333);
  return (Math.imul((x + (x >>> 4)) & 0x0f0f0f0f, 0x01010101) >>> 24) & 0xff;
}

const SQRT3 = Math.sqrt(3);

/**
 * A deterministic Binomial(n, 1/2) draw keyed by `key`: exact (sum of fair hashed bits) for n <= 64, otherwise the
 * normal approximation with an Irwin–Hall(4) variate (σ = √n/2 > 4; tails cut at ±3.46σ, clamped to [0, n]).
 * Integer-only plus IEEE arithmetic and sqrt: identical in every engine.
 */
export function binomialHalf(n: number, key: number): number {
  if (n <= 0) return 0;
  if (n <= 64) {
    let k = 0;
    let left = n;
    let i = 0;
    while (left > 0) {
      const word = mix32((key + Math.imul(i + 1, 0x632be5ab)) >>> 0);
      const bits = left >= 32 ? word : word & (((1 << left) >>> 0) - 1);
      k += popcount(bits >>> 0);
      left -= 32;
      i++;
    }
    return k;
  }
  const a = mix32((key ^ 0xa511e9b3) >>> 0);
  const b = mix32((key ^ 0x63d83595) >>> 0);
  const s = ((a & 0xffff) + 0.5) / 65536 + ((a >>> 16) + 0.5) / 65536 + ((b & 0xffff) + 0.5) / 65536 + ((b >>> 16) + 0.5) / 65536;
  const z = (s - 2) * SQRT3; // unit variance
  const k = Math.round(n / 2 + (z * Math.sqrt(n)) / 2);
  return k < 0 ? 0 : k > n ? n : k;
}

/** Rounds to 12 significant digits through the decimal string (spec-exact), so tiny libm differences vanish. */
export function quantise(x: number, digits = 12): number {
  return x === 0 || !Number.isFinite(x) ? x : Number(x.toPrecision(digits));
}

/** A small deterministic stream of uniforms (for property draws of one object). */
export class Stream {
  private n = 0;
  constructor(private readonly seed: number) {}
  next(): number {
    return u01(h2(this.seed, ++this.n));
  }
  /** Uniform in (0, 1), never 0. */
  open(): number {
    return (h2(this.seed, ++this.n) + 0.5) / TWO32;
  }
  range(a: number, b: number): number {
    return a + (b - a) * this.next();
  }
  int(n: number): number {
    return Math.floor(this.next() * n);
  }
  /** A deterministic Poisson draw (Knuth; mean <= 30). */
  poisson(mean: number): number {
    const l = Math.exp(-mean);
    let k = 0;
    let p = 1;
    for (;;) {
      p *= this.open();
      if (p <= l || k > 60) return k;
      k++;
    }
  }
  /** Standard normal (Box–Muller). */
  normal(): number {
    return Math.sqrt(-2 * Math.log(this.open())) * Math.cos(2 * Math.PI * this.next());
  }
}
