// AiXenix Cosmos Lab: deterministic local systems for stars of the travel model, as scene documents of the data/Scenes
// schema (SI units) that CosmicCore's own parser loads. A procedural system is a generated hypothesis, never a
// discovery; an observed star keeps its catalogue values and gets planets only when asked (flagged hypothetical).
//
// Recipe (stated, approximate): planet count ~ Poisson with a mean by host type; inner orbit a few stellar radii out;
// period ratios 1.4–4; masses rocky/sub-Neptune inside the snow line (2.7 AU √L), giants beyond it with a metallicity-
// dependent chance; orbits pushed apart to >= 10 mutual Hill radii (and inside a quarter of a companion's periapsis);
// small eccentricities and inclinations; up to two moons around giants inside 0.3 Hill radii; an S-type companion star
// for a mass-dependent fraction of main-sequence hosts. Kepler elements -> Cartesian, barycentric recentring, numbers
// quantised to 12 significant digits (identical text in every engine).

import { Stream, h2, quantise } from './rng';
import { evolve, harvardType, type StarProps } from './stars';
import { COSMOS_MODEL_VERSION, type CosmosScene, type LocalizedText, type Provenance, type SystemOptions, type Vec3 } from './types';

const G = 6.6743e-11;
const M_SUN = 1.988409870698051e30;
const R_SUN = 6.957e8;
const L_SUN = 3.828e26;
const M_EARTH = 5.972167867791379e24;
const R_EARTH = 6.3710084e6;
const M_JUP = 1.8981245973360505e27;
const R_JUP = 6.9911e7;
const AU = 149597870700;
const C_MPS = 299792458;
const DEG = Math.PI / 180;

export const SYSTEM_GENERATOR = `aixenix.cosmos.system/${COSMOS_MODEL_VERSION}`;

/** Mean planet count by host. */
function planetMean(p: StarProps): number {
  switch (p.stage) {
    case 'brown_dwarf':
      return 0.4;
    case 'giant':
      return 0.8;
    case 'white_dwarf':
      return 0.3;
    case 'neutron_star':
      return 0.08;
    case 'black_hole':
      return 0;
    default:
      if (p.massSun < 0.6) return 2.4;
      if (p.massSun < 1.5) return 1.8 * Math.min(2, 10 ** (0.3 * p.feH));
      if (p.massSun < 3) return 0.8;
      return 0.3;
  }
}

/** The planet count of a system: the first draw of its stream (also the ModelStar hint). */
export function planetCount(p: StarProps, seed: number): number {
  return Math.min(8, new Stream(h2(seed, 0x0b1)).poisson(planetMean(p)));
}

interface Elements {
  a: number; // m
  e: number;
  i: number; // rad
  node: number;
  peri: number;
  mean: number;
}

/** Two-body state of a body on `el` around a mass sum `mu` (m³/s²), relative to the host. */
export function keplerState(el: Elements, mu: number): { r: Vec3; v: Vec3 } {
  const { a, e } = el;
  let E = el.mean + (e > 0.8 ? Math.PI : 0);
  for (let k = 0; k < 60; k++) {
    const dE = (E - e * Math.sin(E) - el.mean) / (1 - e * Math.cos(E));
    E -= dE;
    if (Math.abs(dE) < 1e-15) break;
  }
  const cosE = Math.cos(E);
  const sinE = Math.sin(E);
  const b = Math.sqrt(1 - e * e);
  const n = Math.sqrt(mu / (a * a * a));
  const den = 1 - e * cosE;
  const px = a * (cosE - e);
  const py = a * b * sinE;
  const vx = (-a * n * sinE) / den;
  const vy = (a * n * b * cosE) / den;
  const [cO, sO, ci, si, cw, sw] = [Math.cos(el.node), Math.sin(el.node), Math.cos(el.i), Math.sin(el.i), Math.cos(el.peri), Math.sin(el.peri)];
  const r11 = cO * cw - sO * sw * ci;
  const r12 = -cO * sw - sO * cw * ci;
  const r21 = sO * cw + cO * sw * ci;
  const r22 = -sO * sw + cO * cw * ci;
  const r31 = sw * si;
  const r32 = cw * si;
  return {
    r: [r11 * px + r12 * py, r21 * px + r22 * py, r31 * px + r32 * py],
    v: [r11 * vx + r12 * vy, r21 * vx + r22 * vy, r31 * vx + r32 * vy],
  };
}

interface Body {
  id: string;
  name: LocalizedText;
  cls: string;
  subclass: string;
  parent: string | null;
  mass: number; // kg
  radius: number; // m
  r: Vec3;
  v: Vec3;
  star?: { teff_k: number; luminosity_w: number; spectral_type: string };
  compact?: Record<string, unknown>;
  profile: string;
  seed: number;
  provenance: Record<string, { kind: string; source?: string; method?: string; note?: string }>;
  candidate: boolean;
  period?: number;
  a?: number;
}

function starProfile(p: StarProps): string {
  switch (p.stage) {
    case 'giant':
      return 'Star_Giant';
    case 'white_dwarf':
      return 'Star_WhiteDwarf';
    case 'neutron_star':
      return 'Star_Neutron';
    case 'black_hole':
      return 'BlackHole_Default';
    case 'brown_dwarf':
      return p.teffK < 1300 ? 'Giant_BrownDwarfT' : 'Giant_BrownDwarfL';
    default:
      return p.teffK >= 10000 ? 'Star_Hot' : p.teffK < 3900 ? 'Star_RedDwarf' : 'Star_MainSequence';
  }
}

function starClass(p: StarProps): string {
  return p.stage === 'white_dwarf' ? 'white_dwarf' : p.stage === 'neutron_star' ? 'neutron_star' : p.stage === 'black_hole' ? 'black_hole' : p.stage === 'brown_dwarf' ? 'brown_dwarf' : 'star';
}

function starBody(id: string, name: LocalizedText, p: StarProps, parent: string | null, seed: number, prov: Body['provenance']): Body {
  const b: Body = {
    id,
    name,
    cls: starClass(p),
    subclass: p.spectralType,
    parent,
    mass: p.massSun * M_SUN,
    radius: p.stage === 'black_hole' ? (2 * G * p.massSun * M_SUN) / (C_MPS * C_MPS) : p.radiusSun * R_SUN,
    r: [0, 0, 0],
    v: [0, 0, 0],
    profile: starProfile(p),
    seed,
    provenance: prov,
    candidate: false,
  };
  if (p.stage === 'black_hole') b.compact = { schwarzschild_radius_m: b.radius };
  else b.star = { teff_k: p.teffK, luminosity_w: p.luminositySun * L_SUN, spectral_type: p.spectralType };
  return b;
}

function planetProfile(cls: string, massE: number, teq: number, host: StarProps, s: Stream): string {
  if (host.stage === 'neutron_star') return 'Planet_Pulsar';
  if (cls === 'gas_giant') {
    if (teq > 1800) return 'Giant_UltraHot';
    if (teq > 900) return 'Giant_HotJupiter';
    if (massE > 4 * 317.8) return 'Giant_SuperJupiter';
    return massE < 0.5 * 317.8 ? 'Giant_Saturn' : 'Giant_Jupiter';
  }
  if (cls === 'neptune_like') return teq > 600 ? 'Giant_WarmNeptune' : teq < 90 ? 'Giant_Uranus' : 'Giant_Neptune';
  if (cls === 'sub_neptune') return 'Giant_SubNeptune';
  if (teq > 1100) return 'Planet_Lava';
  if (teq > 600) return massE > 2 ? 'Planet_SuperEarth' : 'Planet_Mercury';
  if (teq > 320) return s.next() < 0.5 ? 'Planet_Venus' : 'Planet_Desert';
  if (teq > 220) return s.next() < 0.4 ? 'Planet_Ocean' : 'Planet_Temperate';
  if (teq > 150) return 'Planet_ColdDesert';
  return s.next() < 0.5 ? 'Planet_IceBall' : 'Planet_Snowball';
}

const LETTERS = 'bcdefghijk';

export interface SystemInput {
  key: string; // star key (address or obs.<id>)
  galaxyId: string;
  name: LocalizedText;
  props: StarProps;
  seed: number;
  provenance: Provenance;
  /** Observed star: provenance entries for its fields; planets allowed only when hypotheticalPlanets. */
  observedFields?: Record<string, { kind: string; source?: string; note?: string }>;
}

/** Builds the scene document of a star's local system. */
export function buildSystem(inp: SystemInput, opts: SystemOptions = {}): CosmosScene {
  const maxBodies = Math.max(1, Math.min(32, Math.floor(opts.maxBodies ?? 12)));
  const observed = inp.provenance !== 'procedural';
  const allowPlanets = !observed || !!opts.hypotheticalPlanets;
  const host = inp.props;
  const notes: LocalizedText[] = [];
  const procProv = (method: string) => ({ kind: 'procedural', source: SYSTEM_GENERATOR, method });

  const hostProv: Body['provenance'] = observed
    ? { ...(inp.observedFields ?? {}), state: { kind: 'assumed', source: SYSTEM_GENERATOR, note: 'placed at the system origin' } }
    : { mass_kg: procProv('Kroupa IMF + age model'), radius_m: procProv('mass–radius relation'), star: procProv('L(M), Teff from L and R'), state: procProv('system origin') };
  const bodies: Body[] = [starBody('star', inp.name, host, null, h2(inp.seed, 1), hostProv)];
  const Mhost = bodies[0]!.mass;

  // Companion (S-type binary): procedural for model stars only.
  const s = new Stream(h2(inp.seed, 0x0b1));
  const nPlanets = allowPlanets ? Math.min(8, s.poisson(planetMean(host))) : 0;
  const cs = new Stream(h2(inp.seed, 0xc0));
  let aBinMax = Infinity;
  if (!observed && host.stage === 'main_sequence' && maxBodies >= 2) {
    const frac = host.massSun < 0.5 ? 0.25 : host.massSun < 1.5 ? 0.4 : 0.55;
    if (cs.next() < frac) {
      const q = cs.range(0.1, 1);
      const m2 = Math.max(0.08, q * host.massSun);
      const comp = evolve(m2, host.ageGyr, host.feH, cs.next());
      const aBin = AU * 10 ** cs.range(Math.log10(20), Math.log10(2000));
      const eBin = cs.range(0, 0.5);
      const el: Elements = { a: aBin, e: eBin, i: cs.range(0, Math.PI), node: cs.range(0, 2 * Math.PI), peri: cs.range(0, 2 * Math.PI), mean: cs.range(0, 2 * Math.PI) };
      const name = { en: `${inp.name.en} B`, ru: `${inp.name.ru} B` };
      const b = starBody('companion', name, comp, 'star', h2(inp.seed, 2), {
        mass_kg: procProv('mass ratio uniform 0.1–1'),
        radius_m: procProv('mass–radius relation'),
        state: procProv('Kepler elements around the host'),
      });
      const st = keplerState(el, G * (Mhost + b.mass));
      b.r = st.r;
      b.v = st.v;
      b.a = aBin;
      bodies.push(b);
      aBinMax = (aBin * (1 - eBin)) / 4;
      notes.push({ en: 'S-type binary: planets kept inside a quarter of the companion periapsis.', ru: 'Двойная S-типа: планеты внутри четверти перицентра компаньона.' });
    }
  }

  // Planets.
  const lum = Math.max(host.luminositySun, 1e-6);
  const snow = 2.7 * AU * Math.sqrt(host.stage === 'main_sequence' || host.stage === 'giant' ? lum : 1);
  const rStar = bodies[0]!.radius;
  const inner = Math.max(3 * rStar, 0.012 * AU * Math.cbrt(Math.max(host.massSun, 0.05)), 2e8);
  const ps = new Stream(h2(inp.seed, 0x91a));
  let a = inner * 10 ** ps.range(0, 1.2);
  const teffHost = host.stage === 'black_hole' ? 0 : host.teffK;
  type P = { a: number; mass: number; radius: number; cls: string; massE: number };
  const plan: P[] = [];
  for (let k = 0; k < nPlanets; k++) {
    if (k > 0) a *= ps.range(1.4, 4) ** (2 / 3);
    let mass: number;
    let radius: number;
    let cls: string;
    const giantChance = host.stage === 'main_sequence' && host.massSun >= 0.5 ? 0.15 * Math.min(4, 10 ** (1.2 * host.feH)) : 0.05;
    const hotJupiter = a < snow && host.stage === 'main_sequence' && ps.next() < 0.012;
    if ((a > snow && ps.next() < giantChance) || hotJupiter) {
      const mj = 10 ** ps.range(Math.log10(0.1), Math.log10(6));
      mass = mj * M_JUP;
      radius = R_JUP * ps.range(0.9, 1.15) * (hotJupiter ? 1.2 : 1);
      cls = 'gas_giant';
    } else {
      const me = 10 ** ps.range(Math.log10(0.2), Math.log10(a > snow ? 40 : 15));
      mass = me * M_EARTH;
      if (me < 2) {
        radius = R_EARTH * me ** 0.28;
        cls = 'rocky';
      } else if (me < 6) {
        radius = R_EARTH * Math.min(2.2, me ** 0.4);
        cls = 'super_earth';
      } else if (me < 20) {
        radius = R_EARTH * Math.min(3.5, 0.8 * me ** 0.55);
        cls = 'sub_neptune';
      } else {
        radius = R_EARTH * Math.min(4.8, 1.2 * me ** 0.45);
        cls = 'neptune_like';
      }
    }
    // Hill spacing with the previous planet.
    const prev = plan[plan.length - 1];
    if (prev) {
      const rh = Math.cbrt((prev.mass + mass) / (3 * Mhost)) * 0.5 * (prev.a + a);
      if (a - prev.a < 10 * rh) a = prev.a + 10.5 * rh * (1 + 0.5 * Math.cbrt((prev.mass + mass) / (3 * Mhost)));
    }
    if (a > aBinMax || a > 300 * AU) break;
    plan.push({ a, mass, radius, cls, massE: mass / M_EARTH });
  }

  const planetBodies: Body[] = [];
  plan.forEach((pl, k) => {
    const el: Elements = {
      a: pl.a,
      e: Math.min(0.2, Math.abs(ps.normal()) * 0.03),
      i: Math.min(5, Math.abs(ps.normal()) * 1.5) * DEG,
      node: ps.range(0, 2 * Math.PI),
      peri: ps.range(0, 2 * Math.PI),
      mean: ps.range(0, 2 * Math.PI),
    };
    const teq = teffHost > 0 ? teffHost * Math.sqrt(rStar / (2 * pl.a)) * 0.7 ** 0.25 : 30;
    const letter = LETTERS[k] ?? String(k);
    const st = keplerState(el, G * (Mhost + pl.mass));
    const prov = {
      mass_kg: procProv('mass distribution by zone'),
      radius_m: procProv('mass–radius relation'),
      state: procProv('Kepler elements around the host, Hill-spaced'),
      appearance: { kind: 'procedural', source: SYSTEM_GENERATOR, note: 'artistic profile chosen by class and equilibrium temperature' },
    };
    planetBodies.push({
      id: 'p' + letter,
      name: { en: `${inp.name.en} ${letter}`, ru: `${inp.name.ru} ${letter}` },
      cls: 'planet',
      subclass: pl.cls,
      parent: 'star',
      mass: pl.mass,
      radius: pl.radius,
      r: st.r,
      v: st.v,
      profile: planetProfile(pl.cls, pl.massE, teq, host, ps),
      seed: h2(inp.seed, 0x100 + k),
      provenance: prov,
      candidate: observed,
      a: pl.a,
      period: 2 * Math.PI * Math.sqrt(pl.a ** 3 / (G * (Mhost + pl.mass))),
    });
  });

  // Moons of giants.
  const moonBodies: Body[] = [];
  const ms = new Stream(h2(inp.seed, 0x30a));
  for (const p of planetBodies) {
    if (p.subclass !== 'gas_giant' || ms.next() > 0.6) continue;
    const nm = 1 + ms.int(2);
    const hill = p.a! * Math.cbrt(p.mass / (3 * Mhost));
    let am = p.radius * ms.range(8, 20);
    for (let j = 0; j < nm; j++) {
      if (j > 0) am *= ms.range(1.6, 2.5);
      if (am > 0.3 * hill) break;
      const mm = p.mass * 10 ** ms.range(-5, -4);
      const rm = R_EARTH * (mm / M_EARTH) ** 0.3 * 0.9;
      const st = keplerState({ a: am, e: ms.range(0, 0.01), i: ms.range(0, 2) * DEG, node: ms.range(0, 2 * Math.PI), peri: ms.range(0, 2 * Math.PI), mean: ms.range(0, 2 * Math.PI) }, G * (p.mass + mm));
      moonBodies.push({
        id: `${p.id}m${j + 1}`,
        name: { en: `${p.name.en} ${j === 0 ? 'I' : 'II'}`, ru: `${p.name.ru} ${j === 0 ? 'I' : 'II'}` },
        cls: 'moon',
        subclass: 'regular_moon',
        parent: p.id,
        mass: mm,
        radius: rm,
        r: [p.r[0] + st.r[0], p.r[1] + st.r[1], p.r[2] + st.r[2]],
        v: [p.v[0] + st.v[0], p.v[1] + st.v[1], p.v[2] + st.v[2]],
        profile: ms.next() < 0.5 ? 'Planet_IcyMoon' : 'Planet_Callisto',
        seed: h2(inp.seed, 0x200 + moonBodies.length),
        provenance: { mass_kg: procProv('1e-5..1e-4 of the planet'), radius_m: procProv('rocky-ice relation'), state: procProv('Kepler elements inside 0.3 Hill radii') },
        candidate: observed,
        period: 2 * Math.PI * Math.sqrt(am ** 3 / (G * (p.mass + mm))),
        a: am,
      });
    }
  }

  // Body budget: star, companion, then planets inside-out, then moons.
  let all = [...bodies, ...planetBodies, ...moonBodies];
  if (all.length > maxBodies) {
    const keep = new Set<string>();
    for (const b of [...bodies, ...planetBodies, ...moonBodies]) if (keep.size < maxBodies) keep.add(b.id);
    all = all.filter((b) => keep.has(b.id) && (b.parent === null || b.parent === 'star' || keep.has(b.parent)));
  }
  if (planetBodies.length < nPlanets) notes.push({ en: 'Some drawn planets were dropped (stability or body budget).', ru: 'Часть выпавших планет отброшена (устойчивость или лимит тел).' });

  // Barycentric recentring.
  let mt = 0;
  const cr: Vec3 = [0, 0, 0];
  const cv: Vec3 = [0, 0, 0];
  for (const b of all) {
    mt += b.mass;
    for (let k = 0; k < 3; k++) {
      cr[k] += b.mass * b.r[k]!;
      cv[k] += b.mass * b.v[k]!;
    }
  }
  for (const b of all) {
    for (let k = 0; k < 3; k++) {
      b.r[k] = b.r[k]! - cr[k]! / mt;
      b.v[k] = b.v[k]! - cv[k]! / mt;
    }
  }

  const periods = all.filter((b) => b.period).map((b) => b.period!);
  const shortest = periods.length ? Math.min(...periods) : 86400 * 365.25;
  const longest = periods.length ? Math.max(...periods) : 86400 * 365.25;
  const extent = Math.max(...all.map((b) => Math.hypot(...b.r)), 50 * rStar, AU * 0.05);
  const radii = all.map((b) => b.radius);
  const q = quantise;
  const doc = {
    schema: 'aixenix.cosmos.scene/1',
    id: `cosmos.${inp.key}`,
    name: { en: `${inp.name.en} system`, ru: `Система: ${inp.name.ru}` },
    kind: 'authored_procedural',
    group: observed ? 'cosmos_observed_star' : 'cosmos_procedural',
    description: observed
      ? {
          en: `${inp.name.en}: catalogue star${allowPlanets && planetBodies.length ? ' with HYPOTHETICAL procedural planets (not discoveries)' : ' alone (no planets are invented for observed stars)'}.`,
          ru: `${inp.name.ru}: каталожная звезда${allowPlanets && planetBodies.length ? ' с ГИПОТЕТИЧЕСКИМИ процедурными планетами (не открытия)' : ' без планет (для наблюдаемых звёзд планеты не придумываются)'}.`,
        }
      : {
          en: `Procedurally generated system of the model star ${inp.key}: a deterministic hypothesis from the galaxy model, not an observed system.`,
          ru: `Процедурная система модельной звезды ${inp.key}: детерминированная гипотеза модели галактики, а не наблюдаемая система.`,
        },
    epoch: { jd_tdb: 2451545.0, label: 'model epoch (no observational meaning)', basis: 'common instant of every body state in this file' },
    frame: { id: 'cosmos_local_barycentric', origin: 'barycenter', axes: 'right-handed; x-y = generator reference plane, z = its pole (not aligned with the galaxy)', recentred: true },
    physics: {
      model: 'newtonian_point_mass',
      mode_default: 'D',
      softening_m: 0,
      suggested_dt_s: q(Math.max(30, shortest / 600), 6), // innermost period / 600, as the catalogue's generated scenes
      suggested_horizon_s: q(Math.min(longest * 20, 3.15576e10), 6),
      time_scale_hint: q(shortest, 6),
      guard: {
        min_separation_m: q(Math.min(...radii), 6),
        collision: 'surface_contact (sum of physical radii)',
        notes: { en: 'Newtonian point masses; no GR, tides, radiation pressure or gas.', ru: 'Ньютоновские точечные массы; без ОТО, приливов, давления излучения и газа.' },
      },
    },
    camera: { focus: 'barycenter', distance_m: q(3 * extent, 6), pitch_deg: -28, yaw_deg: 35, visual_radius_scale_hint: 1, visual_scale_mode_hint: 'enhanced_bodies' },
    groups: [],
    bodies: all.map((b) => {
      const out: Record<string, unknown> = {
        id: b.id,
        name: b.name,
        class: b.cls,
        subclass: b.subclass,
        parent: b.parent,
        mass_kg: q(b.mass),
        radius_m: q(b.radius),
        position_m: b.r.map((x) => q(x)),
        velocity_mps: b.v.map((x) => q(x)),
        appearance: { profile: b.profile, seed: b.seed, params: {} },
        flags: { msini: false, controversial: false, candidate: b.candidate, conditional: false, excluded_from_start: false, reconstructed_fields: [] },
        provenance: b.provenance,
      };
      if (b.star) out.star = { teff_k: q(b.star.teff_k), luminosity_w: q(b.star.luminosity_w), spectral_type: b.star.spectral_type };
      if (b.compact) out.compact = { schwarzschild_radius_m: q(b.compact.schwarzschild_radius_m as number) };
      return out;
    }),
    assumptions: [
      { id: 'cosmos_generated', text: observed ? { en: 'Star from the catalogue; anything else in this system is hypothetical.', ru: 'Звезда из каталога; всё остальное в системе — гипотеза.' } : { en: 'Every body is generated by the model; nothing here is an observation.', ru: 'Все тела созданы моделью; ничто здесь не является наблюдением.' } },
      ...notes.map((t, i) => ({ id: `note_${i}`, text: t })),
    ],
    sources: [],
    validation: {
      scenario_validated: false,
      core_integration_tested: false,
      data_checks: ['positive masses and radii', 'bound Kepler orbits', '>= 10 mutual Hill radii between planets'],
      status_text: { en: 'Generated; no long-term stability claim.', ru: 'Сгенерировано; без утверждений о долговременной устойчивости.' },
    },
    generator: { version: SYSTEM_GENERATOR, address: inp.key, galaxyId: inp.galaxyId, seed: inp.seed, provenance: inp.provenance },
  };
  return doc as unknown as CosmosScene;
}

/** Star props of an observed star's catalogue values. */
export function observedProps(o: { massSun: number; radiusSun: number; teffK: number; luminositySun: number; spectralType: string; stage: StarProps['stage'] }): StarProps {
  return { massSun: o.massSun, radiusSun: o.radiusSun, teffK: o.teffK, luminositySun: o.luminositySun, spectralType: o.spectralType || harvardType(o.teffK) + 'V', stage: o.stage, ageGyr: 4.6, feH: 0 };
}
