// AiXenix Cosmos Lab: the procedural galaxy model. Exact, storage-free star addressing:
//
// - A galaxy's capacity N is split exactly over its components (ids firstId .. firstId + count - 1 per component).
// - A component's count is split over an octree of its unit cube by deterministic Binomial(n, 1/2) draws along x, then
//   y, then z at every node (rng.binomialHalf: integer-exact, identical in every engine). Children sum exactly to their
//   parent, so the tree is consistent at every depth.
// - Star ids follow depth-first order (children ordered x, then y, then z bit). id -> (leaf cell, index) is a descent
//   that subtracts preceding sibling counts (O(depth)); a cell's first id is the sum of the counts before it.
// - A star's position is a uniform point of its leaf cell (hash of the full 53-bit id) mapped to physical space by the
//   component geometry; its properties come from the component population (stars.ts).

import { geometryOf, axisMeets, type ComponentGeometry, type UnitBox } from './components';
import { diskAxesFromSky, icrsToGalactocentric, SUN_POSITION_PC, vcross, vlen, vnorm, vsub } from './frames';
import { GALAXY_PARAMS, defaultParams } from './params';
import { binomialHalf, h2, hBig, hashString, hn, Stream, u01, u53 } from './rng';
import { drawStar, harvardType, luminosityFromRT, starBrightness, starColor, type StarProps } from './stars';
import { planetCount } from './system';
import {
  COSMOS_MODEL_VERSION,
  type ComponentKind,
  type ComponentParams,
  type GalaxyInput,
  type GalaxySample,
  type GalaxySummary,
  type KnownStarInput,
  type ModelStar,
  type ObservedStar,
  type Provenance,
  type ResolveResult,
  type SampleOptions,
  type SectorInfo,
  type StarAddress,
  type StarsNearResult,
  type Universe,
  type Vec3,
} from './types';

/** Nodes shallower than this keep their 8 child counts cached (bounded: at most 8^0 + ... + 8^5 nodes per component). */
const CACHE_DEPTH = 6;
const MAX_DEPTH = 21;
const MAX_SAMPLE = 2_000_000;
const MAX_CELLS = 4_000_000;
const DEFAULT_CELLS = 400_000;
const MAX_LIMIT = 1_000_000;

/** A bounded integer option: non-finite or absent -> default, then clamped to [min, max]. */
function intOpt(v: unknown, def: number, min: number, max: number): number {
  const x = typeof v === 'number' && Number.isFinite(v) ? Math.floor(v) : def;
  return Math.min(max, Math.max(min, x));
}

export interface ComponentState {
  id: string;
  kind: ComponentKind;
  index: number;
  params: ComponentParams;
  geom: ComponentGeometry;
  starCount: number;
  firstId: number;
  depth: number;
  seed: number;
  cache: Map<number, Float64Array>;
}

export interface GalaxyState {
  summary: GalaxySummary;
  seed: number;
  short: string;
  centre: Vec3;
  /** Galaxy axes in the universe frame. */
  ex: Vec3;
  ey: Vec3;
  ez: Vec3;
  comps: ComponentState[];
}

interface UniverseInternal {
  byId: Map<string, GalaxyState>;
  observed: ObservedStar[];
}

function internal(u: Universe): UniverseInternal {
  return u.internal as UniverseInternal;
}

// ---- building -------------------------------------------------------------------------------------------------------

const SHORT: Record<string, string> = { milky_way: 'MW', m31: 'M31', m32: 'M32', m33: 'M33', m110: 'M110', lmc: 'LMC', smc: 'SMC' };

function isVec3(v: unknown): v is Vec3 {
  return Array.isArray(v) && v.length === 3 && v.every((x) => typeof x === 'number' && Number.isFinite(x));
}

/** Exact integer split of n by weights (largest remainders, ties by index). */
export function splitExact(n: number, weights: number[]): number[] {
  const total = weights.reduce((s, w) => s + Math.max(0, w), 0);
  if (!(total > 0)) return weights.map((_, i) => (i === 0 ? n : 0));
  const raw = weights.map((w) => (n * Math.max(0, w)) / total);
  const out = raw.map((x) => Math.floor(x));
  let left = n - out.reduce((s, x) => s + x, 0);
  const order = raw.map((x, i) => ({ i, f: x - Math.floor(x) })).sort((a, b) => b.f - a.f || a.i - b.i);
  for (let k = 0; left > 0; k = (k + 1) % order.length, left--) out[order[k]!.i]!++;
  return out;
}

function depthFor(n: number): number {
  let d = 1;
  while (d < MAX_DEPTH && 2 * 8 ** d < n) d++;
  return d;
}

function buildGalaxy(g: GalaxyInput): GalaxyState {
  if (!/^[a-z0-9_]+$/.test(g.id)) throw new Error(`cosmos: invalid galaxy id '${g.id}'`);
  const params = GALAXY_PARAMS[g.id] ?? defaultParams(g);
  const provenance: Record<string, Provenance> = { capacity: 'procedural', shape: 'procedural' };
  const assumptions = [...params.assumptions];
  let centre: Vec3;
  if (g.id === 'milky_way') {
    centre = [0, 0, 0];
    provenance.position = 'reconstructed';
  } else if (isVec3(g.galactocentricPc)) {
    centre = [...g.galactocentricPc] as Vec3;
    provenance.position = 'reconstructed';
  } else {
    const d = g.distanceKpc?.value;
    if (!Number.isFinite(g.raDeg) || !Number.isFinite(g.decDeg) || !(typeof d === 'number' && d > 0)) throw new Error(`cosmos: galaxy '${g.id}' has no usable position`);
    centre = icrsToGalactocentric(g.raDeg, g.decDeg, d * 1000);
    provenance.position = 'reconstructed';
  }
  let ex: Vec3 = [1, 0, 0];
  let ez: Vec3 = [0, 0, 1];
  if (g.id === 'milky_way') {
    provenance.orientation = 'reconstructed';
  } else {
    const inc = g.inclinationDeg;
    const pa = g.positionAngleDeg;
    let i = typeof inc === 'number' && Number.isFinite(inc) ? inc : NaN;
    let p = typeof pa === 'number' && Number.isFinite(pa) ? pa : NaN;
    provenance.orientation = Number.isFinite(i) && Number.isFinite(p) ? 'observed' : 'procedural';
    if (!Number.isFinite(p)) {
      p = 0;
      assumptions.push('position angle not given: 0° assumed');
    }
    if (!Number.isFinite(i)) {
      const q = g.axisRatio;
      i = typeof q === 'number' && q > 0 && q < 1 ? (Math.acos(q) * 180) / Math.PI : 60;
      assumptions.push(typeof q === 'number' ? 'inclination from the apparent axis ratio (thin-disk approximation)' : 'inclination not given: 60° assumed');
    }
    const axes = diskAxesFromSky(g.raDeg, g.decDeg, p, i);
    ex = axes.majorAxis;
    ez = axes.normal;
    assumptions.push('which side of the disk is near is not determined by PA and inclination; normal convention stated in frames.ts');
  }
  const ey = vnorm(vcross(ez, ex));
  ex = vnorm(vcross(ey, ez));
  const seed = hashString(`aixenix.cosmos/${COSMOS_MODEL_VERSION}/${g.id}`);
  const capacity = Math.round(params.capacity);
  if (!Number.isSafeInteger(capacity) || capacity < 1) throw new Error(`cosmos: galaxy '${g.id}' capacity invalid`);
  const counts = splitExact(capacity, params.components.map((c) => c.share));
  let first = 0;
  const comps: ComponentState[] = params.components.map((c, index) => {
    const st: ComponentState = {
      id: c.id,
      kind: c.kind,
      index,
      params: c,
      geom: geometryOf(c.geometry),
      starCount: counts[index]!,
      firstId: first,
      depth: depthFor(counts[index]!),
      seed: h2(seed, hashString(c.id)),
      cache: new Map(),
    };
    first += st.starCount;
    return st;
  });
  let thickness = 0;
  for (const c of params.components) {
    const geo = c.geometry;
    thickness = Math.max(thickness, geo.type === 'disk' ? 2 * geo.scaleHeightPc : 2 * geo.scalePc * geo.qz);
  }
  const summary: GalaxySummary = {
    id: g.id,
    name: g.name,
    kind: g.kind,
    centrePc: centre,
    normal: ez,
    majorAxis: ex,
    radiusPc: params.radiusPc,
    thicknessPc: thickness,
    modelStarCount: capacity,
    components: comps.map((c) => ({ id: c.id, kind: c.kind, starCount: c.starCount, firstId: c.firstId })),
    provenance,
    sources: params.sources,
    assumptions,
  };
  return { summary, seed, short: SHORT[g.id] ?? g.id.replace(/_/g, '').toUpperCase(), centre, ex, ey, ez, comps };
}

// ---- observed stars -------------------------------------------------------------------------------------------------

const TEFF_BY_CLASS: Record<string, [number, number]> = {
  O: [50000, 30000],
  B: [30000, 10000],
  A: [10000, 7500],
  F: [7500, 6000],
  G: [6000, 5200],
  K: [5200, 3700],
  M: [3700, 2400],
};

function teffFromSpectral(sp: string | undefined): number | null {
  const m = /^\s*([OBAFGKM])(\d(?:\.\d)?)?/.exec(sp ?? '');
  if (!m) return null;
  const [hi, lo] = TEFF_BY_CLASS[m[1]!]!;
  const sub = m[2] ? Number(m[2]) : 5;
  return hi + ((lo - hi) * sub) / 10;
}

/** Kind of an observed object: the record's objectKind, else inferred from its spectral type, names and aliases. */
export function observedKind(r: KnownStarInput): 'star' | 'white_dwarf' | 'neutron_star' | 'pulsar' | 'black_hole' {
  if (r.objectKind) return r.objectKind;
  const text = [r.spectralType ?? '', r.id, r.name?.en ?? '', ...(r.aliases ?? [])].join(' ');
  if (/black[\s_-]*hole|\bBH\b|sgr[\s_]*a\*?|sgr_a_star/i.test(text)) return 'black_hole';
  if (/pulsar|\bPSR\b|psr_|magnetar/i.test(text)) return 'pulsar';
  if (/neutron/i.test(text)) return 'neutron_star';
  if (/^\s*D[ABOQZCX]/.test(r.spectralType ?? '') || /white[\s_-]*dwarf/i.test(text)) return 'white_dwarf';
  return 'star';
}

const R_SUN_M = 6.957e8;
const RS_M_PER_MSUN = 2953.250077;

function observedStar(r: KnownStarInput): ObservedStar | null {
  let pos: Vec3 | null = null;
  // The Sun is the frame's reference point: always the exact frame constant (records may carry rounded copies).
  if (r.id === 'sun') pos = [...SUN_POSITION_PC] as Vec3;
  else if (isVec3(r.galactocentricPc)) pos = [...r.galactocentricPc] as Vec3;
  else if (r.distancePc && typeof r.distancePc.value === 'number' && r.distancePc.value > 0 && Number.isFinite(r.raDeg) && Number.isFinite(r.decDeg))
    pos = icrsToGalactocentric(r.raDeg!, r.decDeg!, r.distancePc.value);
  if (!pos) return null;
  const reconstructed: string[] = [];
  const kind = observedKind(r);
  const has = (v: number | undefined): v is number => typeof v === 'number' && Number.isFinite(v) && v > 0;
  const base = { key: 'obs.' + r.id, name: r.name, galaxyId: 'milky_way', positionPc: pos, provenance: 'observed' as const, record: r };
  if (kind === 'black_hole' || kind === 'neutron_star' || kind === 'pulsar') {
    // Compact objects: no main-sequence relations. Unknown temperature/luminosity stay 0 (listed as reconstructed).
    let mass = r.massSun;
    if (!has(mass)) {
      mass = kind === 'black_hole' ? 10 : 1.4;
      reconstructed.push('massSun');
    }
    let radius = r.radiusSun;
    if (!has(radius)) {
      radius = kind === 'black_hole' ? (RS_M_PER_MSUN * mass) / R_SUN_M : 1.2e4 / R_SUN_M;
      reconstructed.push('radiusSun');
    }
    if (!has(r.teffK)) reconstructed.push('teffK');
    if (!has(r.luminositySun)) reconstructed.push('luminositySun');
    return {
      ...base,
      massSun: mass,
      radiusSun: radius,
      teffK: has(r.teffK) ? r.teffK : 0,
      luminositySun: has(r.luminositySun) ? r.luminositySun : 0,
      spectralType: r.spectralType || (kind === 'black_hole' ? 'BH' : kind === 'pulsar' ? 'PSR' : 'NS'),
      stage: kind === 'black_hole' ? 'black_hole' : 'neutron_star',
      reconstructed,
    };
  }
  let teff = r.teffK;
  if (!has(teff)) {
    teff = teffFromSpectral(r.spectralType) ?? (kind === 'white_dwarf' ? 10000 : 5772);
    reconstructed.push('teffK');
  }
  let mass = r.massSun;
  let radius = r.radiusSun;
  let lum = r.luminositySun;
  if (!has(mass)) {
    mass = kind === 'white_dwarf' ? 0.6 : has(lum) ? Math.max(0.08, lum ** 0.25) : Math.max(0.08, (teff / 5772) ** 1.6);
    reconstructed.push('massSun');
  }
  if (!has(radius)) {
    radius = kind === 'white_dwarf' ? 0.0126 * (mass / 0.6) ** (-1 / 3) : has(lum) ? Math.sqrt(lum) / (teff / 5772) ** 2 : mass <= 1 ? mass ** 0.8 : mass ** 0.57;
    reconstructed.push('radiusSun');
  }
  if (!has(lum)) {
    lum = luminosityFromRT(radius, teff);
    reconstructed.push('luminositySun');
  }
  const spectralType = r.spectralType || (kind === 'white_dwarf' ? 'D' : harvardType(teff) + 'V');
  if (!r.spectralType) reconstructed.push('spectralType');
  return {
    ...base,
    massSun: mass,
    radiusSun: radius,
    teffK: teff,
    luminositySun: lum,
    spectralType,
    stage: kind === 'white_dwarf' ? 'white_dwarf' : /\b(I{1,3}|IV)\b|III/.test(spectralType) && !/V\s*$/.test(spectralType) ? 'giant' : 'main_sequence',
    reconstructed,
  };
}

/** Builds the universe from content's observed galaxies and stars (once; the result is immutable). */
export function buildUniverse(galaxies: GalaxyInput[], stars: KnownStarInput[] = []): Universe {
  const byId = new Map<string, GalaxyState>();
  for (const g of galaxies) {
    if (byId.has(g.id)) throw new Error(`cosmos: duplicate galaxy id '${g.id}'`);
    byId.set(g.id, buildGalaxy(g));
  }
  const observed: ObservedStar[] = [];
  for (const s of stars) {
    const o = observedStar(s);
    if (o) observed.push(o);
  }
  const inner: UniverseInternal = { byId, observed };
  return { version: COSMOS_MODEL_VERSION, galaxies: [...byId.values()].map((g) => g.summary), internal: inner };
}

export function galaxyState(u: Universe, id: string): GalaxyState | null {
  return internal(u).byId.get(id) ?? null;
}

export function observedStars(u: Universe): ObservedStar[] {
  return internal(u).observed;
}

// ---- the count tree -------------------------------------------------------------------------------------------------

function nodeHash(c: ComponentState, d: number, ix: number, iy: number, iz: number): number {
  return hn(c.seed, d, ix, iy, iz);
}

/** The 8 child counts of a node (order: x bit, then y bit, then z bit), cached for shallow nodes. */
export function childCounts(c: ComponentState, d: number, ix: number, iy: number, iz: number, n: number): Float64Array {
  const cacheKey = d < CACHE_DEPTH ? d + 8 * (ix + 64 * (iy + 64 * iz)) : -1;
  if (cacheKey >= 0) {
    const hit = c.cache.get(cacheKey);
    if (hit) return hit;
  }
  const out = new Float64Array(8);
  const h = nodeHash(c, d, ix, iy, iz);
  const nx0 = binomialHalf(n, h2(h, 1));
  for (let bx = 0; bx < 2; bx++) {
    const nx = bx ? n - nx0 : nx0;
    const ny0 = binomialHalf(nx, h2(h, 2 + bx));
    for (let by = 0; by < 2; by++) {
      const ny = by ? nx - ny0 : ny0;
      const nz0 = binomialHalf(ny, h2(h, 4 + 2 * bx + by));
      out[bx * 4 + by * 2] = nz0;
      out[bx * 4 + by * 2 + 1] = ny - nz0;
    }
  }
  if (cacheKey >= 0) c.cache.set(cacheKey, out);
  return out;
}

interface Leaf {
  ix: number;
  iy: number;
  iz: number;
  index: number;
  count: number;
}

/** Rank r (0 <= r < n of the node) -> leaf cell and index, descending from a node. */
function descend(c: ComponentState, r: number, d0 = 0, ix0 = 0, iy0 = 0, iz0 = 0, n0 = c.starCount): Leaf {
  let n = n0;
  let ix = ix0;
  let iy = iy0;
  let iz = iz0;
  for (let d = d0; d < c.depth; d++) {
    let child = 0;
    if (d < CACHE_DEPTH) {
      const cc = childCounts(c, d, ix, iy, iz, n);
      while (child < 7 && r >= cc[child]!) r -= cc[child++]!;
      n = cc[child]!;
    } else {
      const h = nodeHash(c, d, ix, iy, iz);
      const nx0 = binomialHalf(n, h2(h, 1));
      let bx = 0;
      if (r < nx0) n = nx0;
      else {
        bx = 1;
        r -= nx0;
        n -= nx0;
      }
      const ny0 = binomialHalf(n, h2(h, 2 + bx));
      let by = 0;
      if (r < ny0) n = ny0;
      else {
        by = 1;
        r -= ny0;
        n -= ny0;
      }
      const nz0 = binomialHalf(n, h2(h, 4 + 2 * bx + by));
      let bz = 0;
      if (r < nz0) n = nz0;
      else {
        bz = 1;
        r -= nz0;
        n -= nz0;
      }
      child = bx * 4 + by * 2 + bz;
    }
    ix = 2 * ix + (child >> 2);
    iy = 2 * iy + ((child >> 1) & 1);
    iz = 2 * iz + (child & 1);
  }
  return { ix, iy, iz, index: r, count: n };
}

/** Exact count of a cell and the component-relative id of its first star. */
export function cellCount(c: ComponentState, d: number, ix: number, iy: number, iz: number): { count: number; start: number } {
  let n = c.starCount;
  let start = 0;
  for (let l = 0; l < d; l++) {
    const shift = d - 1 - l;
    const px = ix >> (shift + 1);
    const py = iy >> (shift + 1);
    const pz = iz >> (shift + 1);
    const child = (((ix >> shift) & 1) << 2) | (((iy >> shift) & 1) << 1) | ((iz >> shift) & 1);
    const cc = childCounts(c, l, px, py, pz, n);
    for (let k = 0; k < child; k++) start += cc[k]!;
    n = cc[child]!;
    if (n === 0) break;
  }
  return { count: n, start };
}

// ---- stars ----------------------------------------------------------------------------------------------------------

function starSeeds(g: GalaxyState, id: number): [number, number] {
  return [hBig(g.seed ^ 0x2545f491, id), hBig(g.seed ^ 0x6c8e9cf5, id)];
}

/** Galaxy-frame position of star `id` in its leaf cell. */
function localPosition(c: ComponentState, leaf: Leaf, seedA: number): Vec3 {
  const scale = 2 ** -c.depth;
  return c.geom.toPhysical((leaf.ix + u01(h2(seedA, 1))) * scale, (leaf.iy + u01(h2(seedA, 2))) * scale, (leaf.iz + u01(h2(seedA, 3))) * scale);
}

function toUniverse(g: GalaxyState, p: Vec3): Vec3 {
  return [
    g.centre[0] + p[0] * g.ex[0] + p[1] * g.ey[0] + p[2] * g.ez[0],
    g.centre[1] + p[0] * g.ex[1] + p[1] * g.ey[1] + p[2] * g.ez[1],
    g.centre[2] + p[0] * g.ex[2] + p[1] * g.ey[2] + p[2] * g.ez[2],
  ];
}

function toGalaxy(g: GalaxyState, p: Vec3): Vec3 {
  const d = vsub(p, g.centre);
  return [d[0] * g.ex[0] + d[1] * g.ex[1] + d[2] * g.ex[2], d[0] * g.ey[0] + d[1] * g.ey[1] + d[2] * g.ey[2], d[0] * g.ez[0] + d[1] * g.ez[1] + d[2] * g.ez[2]];
}

function starProps(c: ComponentState, seedB: number): StarProps {
  return drawStar(new Stream(h2(seedB, c.index + 1)), c.params.ageGyr, c.params.feH);
}

function componentOf(g: GalaxyState, id: number): ComponentState {
  let c = g.comps[0]!;
  for (const x of g.comps) if (id >= x.firstId && x.starCount > 0) c = x;
  return c;
}

export function formatAddress(a: StarAddress): string {
  return `${a.version}.${a.galaxyId}.${a.id.toString(36)}`;
}

export function addressOf(galaxyId: string, id: number): string {
  return formatAddress({ version: COSMOS_MODEL_VERSION, galaxyId, id });
}

/** Parses `c1.<galaxy>.<base36 id>`; null unless canonical (lower case, no leading zeros, safe integer). */
export function parseAddress(s: string): StarAddress | null {
  if (typeof s !== 'string' || s.length > 80) return null;
  const m = /^(c[0-9]+)\.([a-z0-9_]+)\.([0-9a-z]+)$/.exec(s);
  if (!m) return null;
  const id = parseInt(m[3]!, 36);
  if (!Number.isSafeInteger(id) || id.toString(36) !== m[3]) return null;
  return { version: m[1]!, galaxyId: m[2]!, id };
}

function makeStar(g: GalaxyState, c: ComponentState, leaf: Leaf, id: number, local?: Vec3): ModelStar {
  const [seedA, seedB] = starSeeds(g, id);
  const p = local ?? localPosition(c, leaf, seedA);
  const props = starProps(c, seedB);
  const id36 = id.toString(36);
  const desig = `${g.short}·${id36.toUpperCase()}`;
  return {
    key: addressOf(g.summary.id, id),
    name: { en: `Model star ${desig}`, ru: `Модельная звезда ${desig}` },
    galaxyId: g.summary.id,
    positionPc: toUniverse(g, p),
    massSun: props.massSun,
    radiusSun: props.radiusSun,
    teffK: props.teffK,
    luminositySun: props.luminositySun,
    spectralType: props.spectralType,
    stage: props.stage,
    provenance: 'procedural',
    address: { version: COSMOS_MODEL_VERSION, galaxyId: g.summary.id, id },
    component: { id: c.id, kind: c.kind },
    cell: { depth: c.depth, xyz: [leaf.ix, leaf.iy, leaf.iz], index: leaf.index },
    ageGyr: props.ageGyr,
    feH: props.feH,
    planetCountHint: planetCount(props, systemSeed(id, g)),
  };
}

/** Seed of a star's local system (deterministic per galaxy and id). */
export function systemSeed(id: number, g: { seed: number }): number {
  return hBig(g.seed ^ 0x1b873593, id);
}

/** Star props of a model star (re-derived; used by the system generator). */
export function modelStarProps(u: Universe, star: ModelStar): StarProps | null {
  const g = galaxyState(u, star.galaxyId);
  if (!g) return null;
  const c = componentOf(g, star.address.id);
  return starProps(c, starSeeds(g, star.address.id)[1]);
}

export function starById(u: Universe, galaxyId: string, id: number): ModelStar | null {
  const g = galaxyState(u, galaxyId);
  if (!g || !Number.isSafeInteger(id) || id < 0 || id >= g.summary.modelStarCount) return null;
  const c = componentOf(g, id);
  return makeStar(g, c, descend(c, id - c.firstId), id);
}

export function resolveAddress(u: Universe, addr: string | StarAddress): ResolveResult {
  let a: StarAddress | null;
  if (typeof addr === 'string') {
    a = parseAddress(addr);
    if (!a) return { ok: false, error: 'syntax', message: `not a star address: '${String(addr).slice(0, 80)}'` };
  } else {
    a = addr && typeof addr === 'object' ? addr : null;
    if (!a || typeof a.galaxyId !== 'string' || typeof a.version !== 'string' || !Number.isSafeInteger(a.id) || a.id < 0)
      return { ok: false, error: 'syntax', message: 'address needs a version, a galaxy id and a non-negative safe integer id' };
  }
  if (a.version !== COSMOS_MODEL_VERSION) return { ok: false, error: 'version', message: `model version '${a.version}' is not '${COSMOS_MODEL_VERSION}'` };
  const g = galaxyState(u, a.galaxyId);
  if (!g) return { ok: false, error: 'unknown_galaxy', message: `no galaxy '${a.galaxyId}'` };
  if (a.id >= g.summary.modelStarCount) return { ok: false, error: 'out_of_range', message: `id ${a.id} >= capacity ${g.summary.modelStarCount}` };
  return { ok: true, star: starById(u, a.galaxyId, a.id)! };
}

// ---- rendering samples ----------------------------------------------------------------------------------------------

interface Cell {
  c: ComponentState;
  d: number;
  ix: number;
  iy: number;
  iz: number;
  count: number;
  start: number; // component-relative first id
}

function boxEmpty(b: UnitBox): boolean {
  return b[0].length === 0 || b[1].length === 0 || b[2].length === 0;
}

function meets(b: UnitBox, d: number, ix: number, iy: number, iz: number): boolean {
  return axisMeets(b[0], ix, d) && axisMeets(b[1], iy, d) && axisMeets(b[2], iz, d);
}

/** Cells of a component meeting a box, refined level by level while the list stays under `maxCells`. */
function cellsInBox(c: ComponentState, box: UnitBox, maxCells: number): Cell[] {
  if (c.starCount === 0 || boxEmpty(box)) return [];
  let level: Cell[] = [{ c, d: 0, ix: 0, iy: 0, iz: 0, count: c.starCount, start: 0 }];
  while (level.length > 0 && level[0]!.d < c.depth) {
    const next: Cell[] = [];
    for (const cell of level) {
      const cc = childCounts(c, cell.d, cell.ix, cell.iy, cell.iz, cell.count);
      let start = cell.start;
      for (let k = 0; k < 8; k++) {
        const n = cc[k]!;
        const ix = 2 * cell.ix + (k >> 2);
        const iy = 2 * cell.iy + ((k >> 1) & 1);
        const iz = 2 * cell.iz + (k & 1);
        if (n > 0 && meets(box, cell.d + 1, ix, iy, iz)) next.push({ c, d: cell.d + 1, ix, iy, iz, count: n, start });
        start += n;
      }
    }
    if (next.length > maxCells) break;
    level = next;
  }
  return level;
}

/**
 * A rendering sample of real model stars: stratified uniform ids over the capacity (or over the cells meeting a region,
 * keeping only stars inside it). Deterministic per (galaxy, count, seed, region).
 */
export function sampleGalaxy(u: Universe, galaxyId: string, count: number, opts: SampleOptions = {}): GalaxySample {
  const g = galaxyState(u, galaxyId);
  if (!g) throw new Error(`cosmos: no galaxy '${galaxyId}'`);
  const want = intOpt(count, 0, 0, MAX_SAMPLE);
  const seed = h2(g.seed ^ 0x7f4a7c15, intOpt(opts.seed, 0, 0, 0xffffffff) >>> 0);
  const ids: number[] = [];
  const pos: number[] = [];
  const col: number[] = [];
  const bri: number[] = [];
  const emit = (c: ComponentState, leaf: Leaf, id: number, keep?: (p: Vec3) => boolean) => {
    const [seedA, seedB] = starSeeds(g, id);
    const p = localPosition(c, leaf, seedA);
    if (keep && !keep(p)) return;
    const props = starProps(c, seedB);
    const rgb = starColor(props);
    ids.push(id);
    pos.push(p[0], p[1], p[2]);
    col.push(rgb[0], rgb[1], rgb[2]);
    bri.push(starBrightness(props));
  };
  let represented = g.summary.modelStarCount;
  let exact = true;
  if (!opts.region) {
    const n = g.summary.modelStarCount;
    const k = Math.min(want, n);
    const stride = n / k;
    let prev = -1;
    for (let i = 0; i < k; i++) {
      let id = k === n ? i : Math.floor(i * stride + u53(h2(seed, 2 * i), h2(seed, 2 * i + 1)) * stride);
      if (id <= prev) id = prev + 1;
      if (id > n - 1 - (k - 1 - i)) id = n - 1 - (k - 1 - i);
      prev = id;
      const c = componentOf(g, id);
      emit(c, descend(c, id - c.firstId), id);
    }
  } else {
    const { centrePc, radiusPc } = opts.region;
    if (!isVec3(centrePc) || !(radiusPc > 0) || !Number.isFinite(radiusPc)) throw new Error('cosmos: region needs a finite centre and a positive radius');
    const lc = toGalaxy(g, centrePc);
    const cells: Cell[] = [];
    for (const c of g.comps) cells.push(...cellsInBox(c, c.geom.boxOfSphere(lc, radiusPc), 4096));
    const cum: number[] = [];
    let total = 0;
    for (const cell of cells) cum.push((total += cell.count));
    const k = Math.min(want, total);
    const stride = total / Math.max(1, k);
    const r2 = radiusPc * radiusPc;
    const inside = (p: Vec3) => (p[0] - lc[0]) ** 2 + (p[1] - lc[1]) ** 2 + (p[2] - lc[2]) ** 2 <= r2;
    let prev = -1;
    for (let i = 0; i < k; i++) {
      let t = k === total ? i : Math.floor(i * stride + u53(h2(seed, 2 * i), h2(seed, 2 * i + 1)) * stride);
      if (t <= prev) t = prev + 1;
      if (t > total - 1 - (k - 1 - i)) t = total - 1 - (k - 1 - i);
      prev = t;
      let lo = 0;
      let hi = cells.length - 1;
      while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (cum[mid]! > t) hi = mid;
        else lo = mid + 1;
      }
      const cell = cells[lo]!;
      const r = t - (cum[lo]! - cell.count);
      const leaf = descend(cell.c, r, cell.d, cell.ix, cell.iy, cell.iz, cell.count);
      emit(cell.c, leaf, cell.c.firstId + cell.start + r, inside);
    }
    represented = k > 0 ? Math.round((total * ids.length) / k) : 0;
    exact = k === total;
  }
  return {
    galaxyId,
    frame: 'galaxy',
    count: ids.length,
    ids: Float64Array.from(ids),
    positions: Float32Array.from(pos),
    colors: Float32Array.from(col),
    brightness: Float32Array.from(bri),
    representedStars: represented,
    representedExact: exact,
  };
}

// ---- neighbourhood --------------------------------------------------------------------------------------------------

/**
 * Every model star inside a sphere, sorted by distance: exact (complete and nearest-first) unless `truncated`. Bounded by
 * the cell budget (default 400k, max 4M) and a candidate cap (max(20k, 8 × limit)); when either cuts the search, the
 * stars are a subset (not necessarily the nearest) and modelCountInRadius is a lower bound.
 */
export function starsNear(u: Universe, galaxyId: string, centrePc: Vec3, radiusPc: number, limit: number, opts: { maxCells?: number } = {}): StarsNearResult {
  const g = galaxyState(u, galaxyId);
  if (!g) throw new Error(`cosmos: no galaxy '${galaxyId}'`);
  if (!isVec3(centrePc) || !(radiusPc > 0) || !Number.isFinite(radiusPc)) throw new Error('cosmos: starsNear needs a finite centre and a positive radius');
  const maxCells = intOpt(opts.maxCells, DEFAULT_CELLS, 1, MAX_CELLS);
  const lim = intOpt(limit, 0, 0, MAX_LIMIT);
  // Memory bound on candidates kept for the distance sort; beyond it the result is a truncated subset.
  const maxFound = Math.min(4 * MAX_LIMIT, Math.max(20_000, 8 * lim));
  const lc = toGalaxy(g, centrePc);
  const r2 = radiusPc * radiusPc;
  const found: { d2: number; c: ComponentState; leaf: Leaf; id: number; p: Vec3 }[] = [];
  let visited = 0;
  let cut = false;
  for (const c of g.comps) {
    if (cut) break;
    const box = c.geom.boxOfSphere(lc, radiusPc);
    if (c.starCount === 0 || boxEmpty(box)) continue;
    const stack: Cell[] = [{ c, d: 0, ix: 0, iy: 0, iz: 0, count: c.starCount, start: 0 }];
    while (stack.length > 0) {
      const cell = stack.pop()!;
      if (++visited > maxCells) {
        cut = true;
        break;
      }
      if (cell.d === c.depth) {
        for (let index = 0; index < cell.count; index++) {
          const id = c.firstId + cell.start + index;
          const leaf: Leaf = { ix: cell.ix, iy: cell.iy, iz: cell.iz, index, count: cell.count };
          const p = localPosition(c, leaf, starSeeds(g, id)[0]);
          const d2 = (p[0] - lc[0]) ** 2 + (p[1] - lc[1]) ** 2 + (p[2] - lc[2]) ** 2;
          if (d2 <= r2) {
            found.push({ d2, c, leaf, id, p });
            if (found.length >= maxFound) {
              cut = true;
              break;
            }
          }
        }
        if (cut) break;
        continue;
      }
      const cc = childCounts(c, cell.d, cell.ix, cell.iy, cell.iz, cell.count);
      const kids: Cell[] = [];
      let start = cell.start;
      for (let k = 0; k < 8; k++) {
        const n = cc[k]!;
        const ix = 2 * cell.ix + (k >> 2);
        const iy = 2 * cell.iy + ((k >> 1) & 1);
        const iz = 2 * cell.iz + (k & 1);
        if (n > 0 && meets(box, cell.d + 1, ix, iy, iz)) kids.push({ c, d: cell.d + 1, ix, iy, iz, count: n, start });
        start += n;
      }
      for (let k = kids.length - 1; k >= 0; k--) stack.push(kids[k]!);
    }
  }
  found.sort((a, b) => a.d2 - b.d2 || a.id - b.id);
  const truncated = cut || found.length > lim;
  return {
    stars: found.slice(0, lim).map((f) => makeStar(g, f.c, f.leaf, f.id, f.p)),
    modelCountInRadius: found.length,
    truncated,
    visitedCells: visited,
  };
}

// ---- sectors and density --------------------------------------------------------------------------------------------

export function sectorInfo(u: Universe, galaxyId: string, posPc: Vec3, depth?: number): SectorInfo[] {
  const g = galaxyState(u, galaxyId);
  if (!g || !isVec3(posPc)) return [];
  const lp = toGalaxy(g, posPc);
  const out: SectorInfo[] = [];
  for (const c of g.comps) {
    const uv = c.geom.toUnit(lp);
    if (!uv) continue;
    const d = Math.max(0, Math.min(c.depth, depth === undefined ? c.depth - 4 : Math.floor(depth)));
    const n = 2 ** d;
    const ix = Math.min(n - 1, Math.floor(uv[0] * n));
    const iy = Math.min(n - 1, Math.floor(uv[1] * n));
    const iz = Math.min(n - 1, Math.floor(uv[2] * n));
    const { count } = cellCount(c, d, ix, iy, iz);
    let lo: Vec3 = [Infinity, Infinity, Infinity];
    let hi: Vec3 = [-Infinity, -Infinity, -Infinity];
    for (let k = 0; k < 8; k++) {
      const q = c.geom.toPhysical(Math.min(1 - 1e-12, (ix + (k >> 2)) / n), Math.min(1 - 1e-12, (iy + ((k >> 1) & 1)) / n), Math.min(1 - 1e-12, (iz + (k & 1)) / n));
      lo = [Math.min(lo[0], q[0]), Math.min(lo[1], q[1]), Math.min(lo[2], q[2])];
      hi = [Math.max(hi[0], q[0]), Math.max(hi[1], q[1]), Math.max(hi[2], q[2])];
    }
    out.push({ key: `${c.id}/${d}/${ix}.${iy}.${iz}`, depth: d, modelStarCount: count, sizePc: vlen(vsub(hi, lo)), densityPerPc3: c.starCount * c.geom.density(lp) });
  }
  return out;
}

/** Expected model stars per pc³ at a point (all components). */
export function densityAt(u: Universe, galaxyId: string, posPc: Vec3): number {
  const g = galaxyState(u, galaxyId);
  if (!g || !isVec3(posPc)) return 0;
  const lp = toGalaxy(g, posPc);
  let s = 0;
  for (const c of g.comps) s += c.starCount * c.geom.density(lp);
  return s;
}

/** The galaxy whose model extent contains the point (the smallest one if several), or null. */
export function galaxyAt(u: Universe, posPc: Vec3): string | null {
  if (!isVec3(posPc)) return null;
  let best: GalaxySummary | null = null;
  for (const g of u.galaxies) {
    if (vlen(vsub(posPc, g.centrePc)) <= g.radiusPc && (!best || g.radiusPc < best.radiusPc)) best = g;
  }
  return best ? best.id : null;
}

/** Universe-frame position of a galaxy-local point (as in GalaxySample.positions). */
export function galaxyToUniverse(u: Universe, galaxyId: string, local: Vec3): Vec3 | null {
  const g = galaxyState(u, galaxyId);
  return g ? toUniverse(g, local) : null;
}

