// AiXenix Cosmos Lab: the universe frame. Galactocentric Cartesian exactly as astropy's Galactocentric frame (v4.0
// defaults for the angles), with R0 = 8122 pc and z_sun = 20.8 pc:
//   x_gc = H · (R · r_icrs − [R0, 0, 0]),  R = R_x(roll0) · R_y(−dec_GC) · R_z(ra_GC),  H = R_y(−asin(z_sun / R0)).
// One rotation plus one translation: the distance of any object from the Sun equals its heliocentric input distance.
// Sources: GRAVITY Collaboration 2018 (A&A 615, L15) R0 = 8.122 kpc; Bennett & Bovy 2019 (MNRAS 482, 1417)
// z_sun = 20.8 pc; Reid & Brunthaler 2004 (ApJ 616, 872) Sgr A* ICRS position; astropy Galactocentric (roll0).

import type { Vec3 } from './types';

export const PC_M = 3.0856775814913673e16; // m (IAU 2015 B2 exact definition)
export const LY_PC = 0.30660139378555057; // 1 Julian light year in pc
export const C_MPS = 299792458;
export const R0_PC = 8122;
export const Z_SUN_PC = 20.8;
export const GC_RA_DEG = 266.4051;
export const GC_DEC_DEG = -28.936175;
export const ROLL0_DEG = 58.5986320306;

const DEG = Math.PI / 180;

type M3 = [number, number, number, number, number, number, number, number, number];

// astropy rotation_matrix (passive, coordinate rotation) about one axis.
function rx(a: number): M3 {
  const c = Math.cos(a);
  const s = Math.sin(a);
  return [1, 0, 0, 0, c, s, 0, -s, c];
}
function ry(a: number): M3 {
  const c = Math.cos(a);
  const s = Math.sin(a);
  return [c, 0, -s, 0, 1, 0, s, 0, c];
}
function rz(a: number): M3 {
  const c = Math.cos(a);
  const s = Math.sin(a);
  return [c, s, 0, -s, c, 0, 0, 0, 1];
}
function mul(a: M3, b: M3): M3 {
  const o = new Array(9).fill(0) as M3;
  for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) for (let k = 0; k < 3; k++) o[i * 3 + j] += a[i * 3 + k]! * b[k * 3 + j]!;
  return o;
}
function apply(m: M3, v: Vec3): Vec3 {
  return [m[0] * v[0] + m[1] * v[1] + m[2] * v[2], m[3] * v[0] + m[4] * v[1] + m[5] * v[2], m[6] * v[0] + m[7] * v[1] + m[8] * v[2]];
}

const R_MAT = mul(mul(rx(ROLL0_DEG * DEG), ry(-GC_DEC_DEG * DEG)), rz(GC_RA_DEG * DEG));
const H_MAT = ry(-Math.asin(Z_SUN_PC / R0_PC));
/** ICRS (equatorial Cartesian) -> galactocentric axes (rotation only). */
export const ICRS_TO_GC: readonly number[] = mul(H_MAT, R_MAT);
const OFFSET: Vec3 = apply(H_MAT, [-R0_PC, 0, 0]);

/** The Sun in the universe frame (pc): [−√(R0² − z²), 0, z_sun]. */
export const SUN_POSITION_PC: Vec3 = [OFFSET[0], OFFSET[1], OFFSET[2]];

/** Unit vector of an ICRS direction in ICRS Cartesian axes. */
export function icrsUnit(raDeg: number, decDeg: number): Vec3 {
  const a = raDeg * DEG;
  const d = decDeg * DEG;
  return [Math.cos(d) * Math.cos(a), Math.cos(d) * Math.sin(a), Math.sin(d)];
}

/** An ICRS-axes vector rotated into galactocentric axes (no translation). */
export function icrsVectorToGalactocentric(v: Vec3): Vec3 {
  return apply(ICRS_TO_GC as M3, v);
}

/** Unit direction of an ICRS position in the universe frame. */
export function icrsDirectionToGalactocentric(raDeg: number, decDeg: number): Vec3 {
  return icrsVectorToGalactocentric(icrsUnit(raDeg, decDeg));
}

/** An object at ICRS (ra, dec) and heliocentric distance (pc) in the universe frame (pc). */
export function icrsToGalactocentric(raDeg: number, decDeg: number, distPc: number): Vec3 {
  const u = icrsUnit(raDeg, decDeg);
  const v = icrsVectorToGalactocentric([u[0] * distPc, u[1] * distPc, u[2] * distPc]);
  return [v[0] + OFFSET[0], v[1] + OFFSET[1], v[2] + OFFSET[2]];
}

// ---- small vector helpers ---------------------------------------------------------------------------------------------

export function vsub(a: Vec3, b: Vec3): Vec3 {
  return [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
}
export function vadd(a: Vec3, b: Vec3): Vec3 {
  return [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
}
export function vscale(a: Vec3, s: number): Vec3 {
  return [a[0] * s, a[1] * s, a[2] * s];
}
export function vdot(a: Vec3, b: Vec3): number {
  return a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
}
export function vcross(a: Vec3, b: Vec3): Vec3 {
  return [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
}
export function vlen(a: Vec3): number {
  return Math.hypot(a[0], a[1], a[2]);
}
export function vnorm(a: Vec3): Vec3 {
  const l = vlen(a);
  return l > 0 ? [a[0] / l, a[1] / l, a[2] / l] : [0, 0, 1];
}

/**
 * The galaxy-frame axes of a disk galaxy seen at (ra, dec) with sky position angle PA (major axis, N through E) and
 * inclination i (0 = face-on), in the universe frame. The sign of the normal (which side is near) is not determined by
 * PA and i alone; the normal is taken towards the observer's side tilted by i (a stated convention).
 */
export function diskAxesFromSky(raDeg: number, decDeg: number, paDeg: number, incDeg: number): { majorAxis: Vec3; normal: Vec3 } {
  const a = raDeg * DEG;
  const d = decDeg * DEG;
  const s = icrsUnit(raDeg, decDeg);
  const east: Vec3 = [-Math.sin(a), Math.cos(a), 0];
  const north: Vec3 = [-Math.sin(d) * Math.cos(a), -Math.sin(d) * Math.sin(a), Math.cos(d)];
  const pa = paDeg * DEG;
  const inc = incDeg * DEG;
  const major = vadd(vscale(north, Math.cos(pa)), vscale(east, Math.sin(pa)));
  const minor = vadd(vscale(north, -Math.sin(pa)), vscale(east, Math.cos(pa)));
  const normal = vadd(vscale(s, -Math.cos(inc)), vscale(minor, Math.sin(inc)));
  return { majorAxis: vnorm(icrsVectorToGalactocentric(major)), normal: vnorm(icrsVectorToGalactocentric(normal)) };
}
