// AiXenix Cosmos Lab: procedural model choices per galaxy (shapes and declared capacity). Observed metadata (position,
// distance, size, orientation, stellar mass) is content's; these are the model's own parameters. Each galaxy lists its
// cited sources and its assumptions. Capacity = declared number of procedural star ids, not a census.
//
// Sources (ids):
//   bhg2016  Bland-Hawthorn & Gerhard 2016, ARA&A 54, 529 (Milky Way disks, bulge/bar, masses, scale lengths/heights)
//   wegg2015 Wegg, Gerhard & Portail 2015, MNRAS 450, 4050 (long bar: half-length ~5 kpc, angle ~28°)
//   vallee2015 Vallée 2015, MNRAS 450, 4277 (four-arm model, pitch ~13°)
//   deason2019 Deason et al. 2019, MNRAS 490, 3426 (stellar halo mass ~1.4e9 M☉)
//   courteau2011 Courteau et al. 2011, ApJ 739, 20 (M31 disk scale length ~5.3 kpc, bulge)
//   tamm2012 Tamm et al. 2012, A&A 546, A4 (M31 stellar mass ~1e11 M☉)
//   vdm2014 van der Marel & Kallivayalil 2014, ApJ 781, 121 (LMC disk scale length ~1.5 kpc, inclination)
//   mcconnachie2012 McConnachie 2012, AJ 144, 4 (Local Group dwarfs: half-light radii, ellipticities, stellar masses)
//   kroupa2001 Kroupa 2001, MNRAS 322, 231 (IMF; mean stellar mass for the capacity)

import type { ComponentParams, GalaxyInput, GalaxyModelParams } from './types';

/** Mean initial stellar mass of the Kroupa IMF over 0.01–150 M☉ (≈0.38 M☉ incl. brown dwarfs); capacity = mass / this. */
export const MEAN_STAR_MASS_MSUN = 0.38;
export const MAX_CAPACITY = 2e12;
export const MIN_CAPACITY = 1000;

const disk = (
  id: string,
  kind: 'thin_disk' | 'thick_disk',
  share: number,
  h: number,
  z0: number,
  rMax: number,
  zMax: number,
  ageGyr: [number, number],
  feH: number,
  arms = 0,
  pitchDeg = 13,
  armContrast = 0.5,
  armPhaseDeg = 0,
  rRefPc = h * 3,
): ComponentParams => ({
  id,
  kind,
  share,
  ageGyr,
  feH,
  geometry: { type: 'disk', scaleLengthPc: h, scaleHeightPc: z0, rMaxPc: rMax, zMaxPc: zMax, arms, armContrast, pitchDeg, armPhaseDeg, rRefPc },
});

const spheroid = (
  id: string,
  kind: ComponentParams['kind'],
  share: number,
  profile: 'hernquist' | 'plummer',
  a: number,
  rMax: number,
  qy: number,
  qz: number,
  ageGyr: [number, number],
  feH: number,
  angleDeg = 0,
  offsetPc: [number, number, number] = [0, 0, 0],
): ComponentParams => ({
  id,
  kind,
  share,
  ageGyr,
  feH,
  geometry: { type: 'spheroid', profile, scalePc: a, rMaxPc: rMax, qy, qz, angleDeg, offsetPc },
});

