/** Default model of a galaxy without explicit params, from its observed kind, size and stellar mass. */
export function defaultParams(g: GalaxyInput): GalaxyModelParams {
  const assumptions: string[] = [];
  const dPc = (g.diameterKpc ?? 0) * 1000;
  let mass = g.stellarMassMsun ?? 0;
  if (!(mass > 0)) {
    mass = dPc > 0 ? 1e10 * (dPc / 30000) ** 2 : 1e8;
    assumptions.push('stellar mass not given: scaled from the diameter');
  }
  const capacity = Math.round(Math.min(MAX_CAPACITY, Math.max(MIN_CAPACITY, mass / MEAN_STAR_MASS_MSUN)));
  assumptions.push('capacity = stellar mass / mean IMF mass (0.38 M☉)');
  let r25 = dPc / 2;
  if (!(r25 > 0)) {
    r25 = 15000 * Math.sqrt(mass / 1e10);
    assumptions.push('diameter not given: scaled from the stellar mass');
  }
  const q = Math.min(1, Math.max(0.2, g.axisRatio ?? 0.7));
  let components: ComponentParams[];
  switch (g.kind) {
    case 'spiral':
    case 'barred_spiral':
    case 'lenticular': {
      const h = r25 / 3.2;
      const lent = g.kind === 'lenticular';
      components = [
        disk('thin', 'thin_disk', lent ? 0.55 : 0.7, h, h / 4, r25 * 1.3, h, [0, 11], -0.1, lent ? 0 : 2, 14, 0.5, 0, 2 * h),
        disk('thick', 'thick_disk', 0.08, h * 0.9, h / 2, r25 * 1.2, 2 * h, [8, 12], -0.5),
        spheroid('bulge', 'bulge', lent ? 0.35 : 0.15, 'hernquist', h / 4, h * 1.5, 0.9, 0.7, [8, 12], 0),
      ];
      if (g.kind === 'barred_spiral') components.push(spheroid('bar', 'bar', 0.1, 'hernquist', h / 2, h * 1.6, 0.35, 0.25, [5, 12], 0, 20));
      assumptions.push('disk scale length = R25 / 3.2, sech² z0 = h / 4', 'two illustrative arms, pitch 14°');
      break;
    }
    case 'elliptical':
    case 'dwarf_elliptical': {
      const re = r25 / 2;
      components = [spheroid('sph', 'spheroid', 1, 'hernquist', re / 1.8153, r25 * 1.5, 1, q, [8, 13], g.kind === 'elliptical' ? 0.1 : -0.8)];
      assumptions.push('Hernquist spheroid with Re = R25 / 2, oblate with the observed axis ratio');
      break;
    }
    case 'dwarf_spheroidal': {
      const a = r25 / 3;
      components = [spheroid('sph', 'spheroid', 1, 'plummer', a, r25 * 1.2, 1, q, [9, 13], -1.7)];
      assumptions.push('Plummer sphere with a = R / 3 (half-light radius), observed axis ratio');
      break;
    }
    case 'irregular':
    default: {
      const h = r25 / 3;
      components = [
        disk('disk', 'thin_disk', 0.7, h, h / 3, r25 * 1.2, h * 1.5, [0, 12], -1, 0),
        spheroid('c0', 'clump', 0.1, 'plummer', h / 4, h, 0.8, 0.7, [0, 0.5], -1, 0, [h * 0.6, h * 0.2, 0]),
        spheroid('c1', 'clump', 0.1, 'plummer', h / 4, h, 0.8, 0.7, [0, 0.5], -1, 0, [-h * 0.4, h * 0.5, 0]),
        spheroid('c2', 'clump', 0.1, 'plummer', h / 4, h, 0.8, 0.7, [0, 0.5], -1, 0, [h * 0.1, -h * 0.7, 0]),
      ];
      assumptions.push('irregular as a thick exponential disk with three young clumps (illustrative positions)');
    }
  }
  const extent = Math.max(...components.map((c) => (c.geometry.type === 'disk' ? c.geometry.rMaxPc : c.geometry.rMaxPc + Math.hypot(...c.geometry.offsetPc))));
  return { capacity, radiusPc: extent, components, sources: ['kroupa2001'], assumptions };
}
