// AiXenix Cosmos Lab: stellar components as maps from the unit cube onto physical space (galaxy frame, pc).
//
// Each component's stars are uniform in the unit cube u = (u0, u1, u2) in [0,1)^3; the map u -> x is a product of
// inverse cumulative distributions, so the physical density follows the component's profile exactly:
//   disk:     u0 -> R (exponential surface density, truncated), u1 -> azimuth (logarithmic spiral modulation),
//             u2 -> z (sech² vertical profile, truncated);
//   spheroid: u0 -> s (Hernquist or Plummer mass profile, truncated), u1 -> cos θ, u2 -> φ; then axis ratios, rotation
//             and offset.
// Every map is monotone in each coordinate, so a physical sphere has a conservative box of unit-space intervals: the
// octree visits only cells in that box (queries), and points are then filtered by true distance (exact results).

import type { DiskGeometry, SpheroidGeometry, Vec3 } from './types';

const TAU = 2 * Math.PI;
const DEG = Math.PI / 180;
/** Unit-space margin added to every query interval (covers inverse-map rounding). */
const EPS = 1e-9;

export type Interval = [number, number];
/** Per unit axis, a list of disjoint intervals in [0, 1]. Empty list on any axis = empty box. */
export type UnitBox = [Interval[], Interval[], Interval[]];

export interface ComponentGeometry {
  /** Unit cube -> galaxy-frame position (pc). */
  toPhysical(u0: number, u1: number, u2: number): Vec3;
  /** Galaxy-frame position -> unit coordinates (for sector lookups); null outside the component's extent. */
  toUnit(p: Vec3): Vec3 | null;
  /** Conservative unit box of a sphere (galaxy frame). */
  boxOfSphere(c: Vec3, r: number): UnitBox;
  /** Probability density per pc³ (integrates to 1 over the component). */
  density(p: Vec3): number;
  /** Bounding radius from the galaxy centre (pc). */
  extentPc: number;
}

function clamp01(x: number): number {
  return x < 0 ? 0 : x > 1 ? 1 : x;
}

function interval(a: number, b: number): Interval[] {
  const lo = clamp01(Math.min(a, b) - EPS);
  const hi = clamp01(Math.max(a, b) + EPS);
  return hi > lo ? [[lo, hi]] : [];
}

/** An angular interval [a, b] (radians, b >= a) as unit intervals of angle / 2π, split at the wrap. */
function angularIntervals(a: number, b: number): Interval[] {
  if (b - a >= TAU - 2 * EPS) return [[0, 1]];
  let lo = (a - EPS * TAU) / TAU;
  let hi = (b + EPS * TAU) / TAU;
  const shift = Math.floor(lo);
  lo -= shift;
  hi -= shift;
  if (hi <= 1) return [[lo, hi]];
  return [
    [0, Math.min(1, hi - 1)],
    [lo, 1],
  ];
}

// ---- exponential disk -----------------------------------------------------------------------------------------------

/** Mass fraction of an exponential disk inside x = R / h (series below 0.01: no cancellation near the centre). */
function expCdf(x: number): number {
  if (x < 0.01) {
    const x2 = x * x;
    return x2 * (0.5 + x * (-1 / 3 + x * (1 / 8 + x * (-1 / 30 + x / 144))));
  }
  return -Math.expm1(-x) - x * Math.exp(-x);
}

/** Inverse of expCdf by a precomputed table plus safeguarded Newton steps. */
class ExpCdfInverse {
  private readonly table: Float64Array;
  private readonly n = 2048;
  constructor(private readonly xMax: number) {
    const fMax = expCdf(xMax);
    this.table = new Float64Array(this.n + 1);
    for (let k = 0; k <= this.n; k++) this.table[k] = this.solve((fMax * k) / this.n, 0, xMax, 80);
  }
  private solve(q: number, lo: number, hi: number, iters: number): number {
    for (let i = 0; i < iters; i++) {
      const mid = 0.5 * (lo + hi);
      if (expCdf(mid) < q) lo = mid;
      else hi = mid;
    }
    return 0.5 * (lo + hi);
  }
  /** x with expCdf(x) = q, q in [0, expCdf(xMax)]: bracketed Newton from the table, converged to the last bits. */
  invert(q: number, fMax: number): number {
    if (!(q > 0)) return 0;
    if (q >= fMax) return this.xMax;
    const t = (q / fMax) * this.n;
    const k = Math.min(this.n - 1, Math.max(0, Math.floor(t)));
    let lo = k > 0 ? this.table[k - 1]! : 0;
    let hi = k + 2 <= this.n ? this.table[k + 2]! : this.xMax;
    let x = this.table[k]! + (this.table[k + 1]! - this.table[k]!) * (t - k);
    if (!(x > lo && x < hi)) x = 0.5 * (lo + hi);
    for (let i = 0; i < 200; i++) {
      const f = expCdf(x) - q;
      if (f === 0) return x;
      if (f < 0) lo = x;
      else hi = x;
      const d = x * Math.exp(-x);
      let next = d > 0 ? x - f / d : NaN;
      if (!(next > lo && next < hi)) next = 0.5 * (lo + hi);
      if (next === x || next <= lo || next >= hi) return x;
      x = next;
    }
    return x;
  }
}

export function diskGeometry(g: DiskGeometry): ComponentGeometry {
  const h = g.scaleLengthPc;
  const z0 = g.scaleHeightPc;
  const xMax = g.rMaxPc / h;
  const fMax = expCdf(xMax);
  const inv = new ExpCdfInverse(xMax);
  const tz = Math.tanh(g.zMaxPc / z0);
  const m = g.arms;
  const A = m > 0 ? Math.min(0.9, Math.max(0, g.armContrast)) : 0;
  const cotPitch = 1 / Math.tan(Math.max(1, Math.min(89, g.pitchDeg)) * DEG);
  const phase0 = g.armPhaseDeg * DEG;
  const rRef = g.rRefPc;

  const psi = (R: number) => phase0 + Math.log(Math.max(R, 1) / rRef) * cotPitch;
  /** Azimuth of unit-angle t at radius R: φ = t + (A/m) sin(m t − ψ(R)); density ∝ 1 / (1 + A cos(m t − ψ)). */
  const warp = (t: number, ps: number) => (A > 0 ? t + (A / m) * Math.sin(m * t - ps) : t);
  /** t with warp(t, ψ) = φ (monotone: dφ/dt = 1 + A cos(...) >= 1 − A > 0); bracketed Newton to the last bits. */
  const unwarp = (phi: number, ps: number) => {
    if (A === 0) return phi;
    let lo = phi - A / m - 1e-12;
    let hi = phi + A / m + 1e-12;
    let t = phi;
    for (let i = 0; i < 200; i++) {
      const f = warp(t, ps) - phi;
      if (f === 0) return t;
      if (f < 0) lo = t;
      else hi = t;
      let next = t - f / (1 + A * Math.cos(m * t - ps));
      if (!(next > lo && next < hi)) next = 0.5 * (lo + hi);
      if (next === t || next <= lo || next >= hi) return t;
      t = next;
    }
    return t;
  };
  const rOf = (u0: number) => h * inv.invert(u0 * fMax, fMax);
  const uOfR = (R: number) => expCdf(Math.min(R, g.rMaxPc) / h) / fMax;
  const zOf = (u2: number) => z0 * Math.atanh(Math.max(-1 + 1e-16, Math.min(1 - 1e-16, (2 * u2 - 1) * tz)));
  const uOfZ = (z: number) => 0.5 * (Math.tanh(Math.max(-g.zMaxPc, Math.min(g.zMaxPc, z)) / z0) / tz + 1);

  return {
    extentPc: Math.hypot(g.rMaxPc, g.zMaxPc),
    toPhysical(u0, u1, u2) {
      const R = rOf(u0);
      const phi = warp(TAU * u1, psi(R));
      return [R * Math.cos(phi), R * Math.sin(phi), zOf(u2)];
    },
    toUnit(p) {
      const R = Math.hypot(p[0], p[1]);
      if (R > g.rMaxPc || Math.abs(p[2]) > g.zMaxPc) return null;
      const t = unwarp(Math.atan2(p[1], p[0]), psi(R));
      const u1 = (((t / TAU) % 1) + 1) % 1;
      return [uOfR(R), u1, uOfZ(p[2])];
    },
    boxOfSphere(c, r) {
      const Rc = Math.hypot(c[0], c[1]);
      const R1 = Math.max(0, Rc - r);
      const R2 = Math.min(g.rMaxPc, Rc + r);
      const z1 = Math.max(-g.zMaxPc, c[2] - r);
      const z2 = Math.min(g.zMaxPc, c[2] + r);
      if (R1 > g.rMaxPc || z1 > z2) return [[], [], []];
      let ang: Interval[];
      if (Rc <= r) ang = [[0, 1]];
      else {
        const alpha = Math.asin(Math.min(1, r / Rc));
        const phiC = Math.atan2(c[1], c[0]);
        const psM = psi(0.5 * (R1 + R2));
        const delta = A > 0 ? (A / m / (1 - A)) * Math.abs(psi(R2) - psi(Math.max(R1, 1))) + 1e-9 : 0;
        ang = angularIntervals(unwarp(phiC - alpha, psM) - delta, unwarp(phiC + alpha, psM) + delta);
      }
      return [interval(uOfR(R1), uOfR(R2)), ang, interval(uOfZ(z1), uOfZ(z2))];
    },
    density(p) {
      const R = Math.hypot(p[0], p[1]);
      if (R > g.rMaxPc || Math.abs(p[2]) > g.zMaxPc) return 0;
      const radial = Math.exp(-R / h) / (TAU * h * h * fMax); // surface density per pc² (axisymmetric part)
      let arm = 1;
      if (A > 0) {
        const ps = psi(R);
        const t = unwarp(Math.atan2(p[1], p[0]), ps);
        arm = 1 / (1 + A * Math.cos(m * t - ps));
      }
      const s = 1 / Math.cosh(p[2] / z0);
      return radial * arm * ((s * s) / (2 * z0 * tz));
    },
  };
}

// ---- spheroids ------------------------------------------------------------------------------------------------------

export function spheroidGeometry(g: SpheroidGeometry): ComponentGeometry {
  const a = g.scalePc;
  const sMax = g.rMaxPc;
  const plummer = g.profile === 'plummer';
  const cdf = (s: number) => (plummer ? (s * s * s) / Math.pow(s * s + a * a, 1.5) : (s * s) / ((s + a) * (s + a)));
  const pdf = (s: number) => (plummer ? (3 * a * a * s * s) / Math.pow(s * s + a * a, 2.5) : (2 * a * s) / Math.pow(s + a, 3));
  const fMax = cdf(sMax);
  const sOf = (u0: number) => {
    const q = u0 * fMax;
    if (q <= 0) return 0;
    if (plummer) {
      const w = Math.pow(q, 2 / 3);
      return w >= 1 ? sMax : Math.min(sMax, a * Math.sqrt(w / (1 - w)));
    }
    const w = Math.sqrt(q);
    return w >= 1 ? sMax : Math.min(sMax, (a * w) / (1 - w));
  };
  const ca = Math.cos(g.angleDeg * DEG);
  const sa = Math.sin(g.angleDeg * DEG);
  const qMin = Math.min(g.qy, g.qz, 1);
  /** Galaxy frame -> normalised spheroid coordinates (unit axis ratios). */
  const normalise = (p: Vec3): Vec3 => {
    const x = p[0] - g.offsetPc[0];
    const y = p[1] - g.offsetPc[1];
    const z = p[2] - g.offsetPc[2];
    return [ca * x + sa * y, (-sa * x + ca * y) / g.qy, z / g.qz];
  };

  return {
    extentPc: sMax + Math.hypot(g.offsetPc[0], g.offsetPc[1], g.offsetPc[2]),
    toPhysical(u0, u1, u2) {
      const s = sOf(u0);
      const ct = 2 * u1 - 1;
      const st = Math.sqrt(Math.max(0, 1 - ct * ct));
      const ph = TAU * u2;
      const x = s * st * Math.cos(ph);
      const y = s * st * Math.sin(ph) * g.qy;
      const z = s * ct * g.qz;
      return [ca * x - sa * y + g.offsetPc[0], sa * x + ca * y + g.offsetPc[1], z + g.offsetPc[2]];
    },
    toUnit(p) {
      const n = normalise(p);
      const s = Math.hypot(n[0], n[1], n[2]);
      if (s > sMax) return null;
      const ct = s > 0 ? n[2] / s : 0;
      const ph = Math.atan2(n[1], n[0]);
      return [cdf(s) / fMax, (ct + 1) / 2, (((ph / TAU) % 1) + 1) % 1];
    },
    boxOfSphere(c, r) {
      const n = normalise(c);
      const rn = r / qMin;
      const sc = Math.hypot(n[0], n[1], n[2]);
      const s1 = Math.max(0, sc - rn);
      const s2 = Math.min(sMax, sc + rn);
      if (s1 > sMax) return [[], [], []];
      const radial = interval(cdf(s1) / fMax, cdf(s2) / fMax);
      if (sc <= rn) return [radial, [[0, 1]], [[0, 1]]];
      const alpha = Math.asin(Math.min(1, rn / sc));
      const th = Math.acos(Math.max(-1, Math.min(1, n[2] / sc)));
      const th1 = Math.max(0, th - alpha);
      const th2 = Math.min(Math.PI, th + alpha);
      const cosI = interval((Math.cos(th2) + 1) / 2, (Math.cos(th1) + 1) / 2);
      let ang: Interval[];
      if (th1 <= 0 || th2 >= Math.PI) ang = [[0, 1]];
      else {
        const beta = Math.asin(Math.min(1, Math.sin(alpha) / Math.sin(th)));
        const ph = Math.atan2(n[1], n[0]);
        ang = beta >= Math.PI / 2 - 1e-12 ? [[0, 1]] : angularIntervals(ph - beta, ph + beta);
      }
      return [radial, cosI, ang];
    },
    density(p) {
      const n = normalise(p);
      const s = Math.hypot(n[0], n[1], n[2]);
      if (s > sMax) return 0;
      const ss = Math.max(s, 1e-3 * a);
      return pdf(ss) / (fMax * 4 * Math.PI * ss * ss * g.qy * g.qz);
    },
  };
}

export function geometryOf(g: DiskGeometry | SpheroidGeometry): ComponentGeometry {
  return g.type === 'disk' ? diskGeometry(g) : spheroidGeometry(g);
}

/** True when the node [i, i+1) / 2^d on one axis meets any interval. */
export function axisMeets(list: Interval[], i: number, d: number): boolean {
  const size = 1 / 2 ** d;
  const lo = i * size;
  const hi = lo + size;
  for (const [a, b] of list) if (a < hi && b > lo) return true;
  return false;
}
