// AiXenix Cosmos Lab: properties of procedural stars from their component's population. Simple, stated relations
// (approximate, for a travel model; not stellar evolution):
// - initial mass: Kroupa 2001 broken power law, 0.01–150 M☉ (brown dwarfs included);
// - age uniform in the component's range, [Fe/H] = component mean ± 0.25;
// - main-sequence lifetime t = 10 Gyr · M^−2.5; giants for 10 % of that after it (M >= 0.8);
// - remnants: white dwarf (initial-final mass relation of Kalirai et al. 2008), neutron star (8–25 M☉),
//   black hole (>= 25 M☉, 30 % of the initial mass, at least 3 M☉);
// - main-sequence L(M), R(M) piecewise power laws, mild brightening with fractional age; Teff from L and R.

import { Stream } from './rng';
import type { StellarStage } from './types';

export interface StarProps {
  massSun: number;
  radiusSun: number;
  teffK: number;
  luminositySun: number;
  spectralType: string;
  stage: StellarStage;
  ageGyr: number;
  feH: number;
}

const T_SUN = 5772;
const R_SUN_M = 6.957e8;
const SCHWARZSCHILD_M_PER_MSUN = 2953.250077;

// Kroupa 2001: dN/dm ∝ m^-α with α = 0.3 (0.01–0.08), 1.3 (0.08–0.5), 2.3 (0.5–150), continuous at the breaks.
const SEGMENTS = (() => {
  const bounds = [0.01, 0.08, 0.5, 150];
  const alphas = [0.3, 1.3, 2.3];
  const k = [1, 0, 0];
  k[1] = k[0]! * 0.08 ** (alphas[1]! - alphas[0]!);
  k[2] = k[1]! * 0.5 ** (alphas[2]! - alphas[1]!);
  const weights = alphas.map((a, i) => {
    const lo = bounds[i]!;
    const hi = bounds[i + 1]!;
    return (k[i]! * (hi ** (1 - a) - lo ** (1 - a))) / (1 - a);
  });
  const total = weights.reduce((s, w) => s + w, 0);
  let acc = 0;
  const cum = weights.map((w) => (acc += w / total));
  return { bounds, alphas, cum };
})();

export function sampleImf(u: number, v: number): number {
  let i = 0;
  while (i < 2 && u > SEGMENTS.cum[i]!) i++;
  const a = SEGMENTS.alphas[i]!;
  const lo = SEGMENTS.bounds[i]!;
  const hi = SEGMENTS.bounds[i + 1]!;
  const e = 1 - a;
  return (lo ** e + v * (hi ** e - lo ** e)) ** (1 / e);
}

export function msLifetimeGyr(m: number): number {
  return 10 * m ** -2.5;
}

function msLuminosity(m: number): number {
  if (m < 0.43) return 0.23 * m ** 2.3;
  if (m < 2) return m ** 4;
  if (m < 55) return 1.4 * m ** 3.5;
  return 32000 * m;
}

function msRadius(m: number): number {
  return m <= 1 ? m ** 0.8 : m ** 0.57;
}

const CLASSES: [string, number, number][] = [
  ['O', 30000, 50000],
  ['B', 10000, 30000],
  ['A', 7500, 10000],
  ['F', 6000, 7500],
  ['G', 5200, 6000],
  ['K', 3700, 5200],
  ['M', 2400, 3700],
];

/** Harvard class and subtype from Teff ('G2', 'M4'); below 2400 K the L/T/Y sequence. */
export function harvardType(teff: number): string {
  if (teff < 2400) {
    if (teff >= 1300) return 'L' + Math.min(9, Math.max(0, Math.floor((10 * (2400 - teff)) / 1100)));
    if (teff >= 600) return 'T' + Math.min(9, Math.max(0, Math.floor((10 * (1300 - teff)) / 700)));
    return 'Y' + Math.min(4, Math.max(0, Math.floor((5 * (600 - teff)) / 350)));
  }
  for (const [c, lo, hi] of CLASSES) {
    if (teff >= lo) {
      const sub = Math.min(9, Math.max(0, Math.floor((10 * (hi - teff)) / (hi - lo))));
      return c + sub;
    }
  }
  return 'M9';
}

export function luminosityFromRT(radiusSun: number, teffK: number): number {
  return radiusSun * radiusSun * (teffK / T_SUN) ** 4;
}

/** Properties of one star of a population (age range Gyr, mean [Fe/H]) from its stream. */
export function drawStar(s: Stream, ageGyr: [number, number], feHMean: number): StarProps {
  const age = s.range(ageGyr[0], ageGyr[1]);
  const feH = feHMean + 0.25 * (2 * s.next() - 1);
  const m0 = sampleImf(s.next(), s.next());
  return evolve(m0, age, feH, s.next());
}

/** The state of a star of initial mass m0 (M☉) at age (Gyr). `w` is a uniform for scatter. */
export function evolve(m0: number, age: number, feH: number, w: number): StarProps {
  if (m0 < 0.08) {
    const teff = Math.min(2800, Math.max(300, 2600 * (m0 / 0.075) ** 0.8 * Math.max(age, 0.01) ** -0.3));
    const radius = 0.1 * (1 + 0.2 * w);
    return { massSun: m0, radiusSun: radius, teffK: teff, luminositySun: luminosityFromRT(radius, teff), spectralType: harvardType(Math.min(teff, 2399)), stage: 'brown_dwarf', ageGyr: age, feH };
  }
  const tms = msLifetimeGyr(m0);
  if (age < tms) {
    const f = age / tms;
    const lum = msLuminosity(m0) * (1 + 0.6 * f);
    const radius = msRadius(m0) * (1 + 0.25 * f);
    const teff = T_SUN * (lum / (radius * radius)) ** 0.25;
    return { massSun: m0, radiusSun: radius, teffK: teff, luminositySun: lum, spectralType: harvardType(teff) + 'V', stage: 'main_sequence', ageGyr: age, feH };
  }
  if (age < 1.1 * tms && m0 >= 0.8) {
    const f = (age - tms) / (0.1 * tms);
    const radius = 10 * m0 ** 0.6 * (1 + 4 * f) * (0.9 + 0.2 * w);
    const teff = 5000 - 1300 * f;
    return { massSun: m0, radiusSun: radius, teffK: teff, luminositySun: luminosityFromRT(radius, teff), spectralType: harvardType(teff) + 'III', stage: 'giant', ageGyr: age, feH };
  }
  const tCool = Math.max(0, age - 1.1 * tms);
  if (m0 < 8) {
    const mwd = Math.min(1.35, 0.109 * m0 + 0.394);
    const radius = 0.0126 * (mwd / 0.6) ** (-1 / 3);
    const teff = Math.max(3500, 25000 * (1 + tCool / 0.1) ** -0.4);
    return { massSun: mwd, radiusSun: radius, teffK: teff, luminositySun: luminosityFromRT(radius, teff), spectralType: 'DA' + Math.min(9, Math.max(1, Math.round(50400 / teff))), stage: 'white_dwarf', ageGyr: age, feH };
  }
  if (m0 < 25) {
    const radius = 1.2e4 / R_SUN_M;
    const teff = Math.max(3e4, 1e6 * (1 + tCool / 1e-4) ** -0.5);
    return { massSun: 1.4, radiusSun: radius, teffK: teff, luminositySun: luminosityFromRT(radius, teff), spectralType: 'NS', stage: 'neutron_star', ageGyr: age, feH };
  }
  const mbh = Math.max(3, 0.3 * m0);
  return { massSun: mbh, radiusSun: (SCHWARZSCHILD_M_PER_MSUN * mbh) / R_SUN_M, teffK: 0, luminositySun: 0, spectralType: 'BH', stage: 'black_hole', ageGyr: age, feH };
}

/** Approximate linear-RGB colour of a blackbody (normalised to max 1). */
export function blackbodyLinear(teff: number): [number, number, number] {
  const t = Math.min(40000, Math.max(1000, teff)) / 100;
  let r: number;
  let g: number;
  let b: number;
  if (t <= 66) {
    r = 255;
    g = 99.4708025861 * Math.log(t) - 161.1195681661;
    b = t <= 19 ? 0 : 138.5177312231 * Math.log(t - 10) - 305.0447927307;
  } else {
    r = 329.698727446 * (t - 60) ** -0.1332047592;
    g = 288.1221695283 * (t - 60) ** -0.0755148492;
    b = 255;
  }
  const lin = (c: number) => (Math.min(255, Math.max(0, c)) / 255) ** 2.2;
  const out: [number, number, number] = [lin(r), lin(g), lin(b)];
  const m = Math.max(out[0], out[1], out[2], 1e-6);
  return [out[0] / m, out[1] / m, out[2] / m];
}

/** Display colour of a star (linear rgb). Remnants get conventional hues (no thermal light for black holes). */
export function starColor(p: StarProps): [number, number, number] {
  if (p.stage === 'black_hole') return [0.55, 0.3, 0.12];
  if (p.stage === 'neutron_star') return [0.55, 0.8, 1];
  return blackbodyLinear(p.teffK);
}

/** Relative display brightness in [0.02, 1] from log luminosity (1e-4 .. 1e6 L☉). */
export function starBrightness(p: StarProps): number {
  if (p.luminositySun <= 0) return 0.02;
  return Math.min(1, Math.max(0.02, (Math.log10(p.luminositySun) + 4) / 10));
}
